import * as React from 'react';
import { 
    Avatar,
    Checkbox,
    IconButton,
    ListItem, 
    ListItemAvatar, 
    ListItemButton, 
    ListItemIcon, 
    ListItemText,
    Zoom,
    Box,
    Divider,
    Typography,
    Stack,
    Badge
} from "@mui/material";
import ExpandMoreRoundedIcon from '@mui/icons-material/ExpandMoreRounded';
import { styled } from '@mui/material/styles';

const StyledBadge = styled(Badge)(({ theme }) => ({
    '& .MuiBadge-badge': {
      right: 35,
      top: 18,
      border: `2px solid ${theme.palette.background.paper}`,
      padding: '0 4px',
    },
  }));

export default function ContactItem ({
        mode, 
        date,
        name,
        onClick,
        divider,
        message, 
        avatarProps, 
        checkboxProps,
        secondaryAction, 
        news,
        selected,
        disabledSecondaryAction
    }) {
        
    const [showMoreOption, setShowOption] = React.useState(false);

    return (
        <React.Fragment>
                <ListItem
                    disablePadding
                    onClick={onClick}
                    selected={selected}
                    {...disabledSecondaryAction ? {} : {
                        onMouseEnter() { setShowOption(true) },
                        onMouseLeave() { setShowOption(false) },
                        secondaryAction:
                        (<StyledBadge badgeContent={news} color="primary">
                            <Stack
                                sx={{
                                    display:'flex',
                                }}
                            >
                                <Box 
                                    sx={{
                                        display:'flex', 
                                        alignItems: 'right', 
                                        justifyContent: 'right',
                                        }}
                                >
                                    <Zoom in={showMoreOption}>
                                        <IconButton size="small" 
                                            {...secondaryAction} 
                                            sx={{mr: -1}}>
                                            <ExpandMoreRoundedIcon/>
                                        </IconButton>
                                    </Zoom>
                                </Box>
                                <Typography variant="caption">{date}</Typography>
                            </Stack>
                        </StyledBadge>),
                    }}
                >
                    <ListItemButton
                    >
                        
                        <ListItemAvatar>
                            <Avatar
                                {...avatarProps}
                            />
                        </ListItemAvatar>
                        <ListItemText
                            primary={name}
                            sx={{flexGrow: 1}}
                            secondary={message}
                            secondaryTypographyProps={{
                                variant: 'body2',
                                component: 'div',
                                sx:{
                                    textOverflow: 'ellipsis',  
                                    whiteSpace: 'nowrap', 
                                    overflow: 'hidden',
                                    flexGrow: 1,
                                    width: '80%'
                                }
                            }}
                            primaryTypographyProps={{
                                component:"div",
                                sx:{
                                    textOverflow: 'ellipsis',  
                                    whiteSpace: 'nowrap', 
                                    overflow: 'hidden',
                                    flexGrow: 1,
                                }
                            }}
                        />
                        {mode === 'select' &&
                            <Zoom in>
                                <ListItemIcon
                                    sx={{justifyContent: 'right', display: 'flex'}}
                                >
                                    <Checkbox
                                        edge="start"
                                        disableRipple
                                        {...checkboxProps}
                                    />
                                </ListItemIcon>
                            </Zoom>
                        }
                    </ListItemButton>
                </ListItem>
                {divider && <Divider variant="inset" component="li" />}
        </React.Fragment>
    )
}