import * as React from 'react';
import {
    Box, 
    DialogActions, 
    DialogContent,
    Button,
    Typography,
    IconButton,
    Avatar,
} from '@mui/material'
import TextFieldController from "../../../components/TextFieldController";
import { close } from '../../../redux/apps/livingroom/fastContactNav';
import { useDispatch, useSelector } from 'react-redux';
import Groups2RoundedIcon from '@mui/icons-material/Groups2Rounded';
import asyncGetFile from '../../../services/asyncGetFile';
import serverPath from '../../../services/serverPath';
import useAxios from 'axios-hooks';
import { LoadingButton } from '@mui/lab';

export default function CreateRoom ({usersRef, onPrevious}) {
    const dispatch = useDispatch();
    const [file, setFile] = React.useState(null);
    const [{loading, error, data}, refetch, cancel] = useAxios(URL_ROOM, {manual: true});
    const {id:userId, token} = useSelector(state => state.user.value);
    const [checking, setChecking] = React.useState([]);
    const refs = {
        name: React.useRef(''),
        description: React.useRef(''),
    }
  
    const handleCreateRoom = () => {
        const errors = [];
        Object.keys(refs).forEach(key => {
            if(!refs[key].current) 
                errors.push(key);
        })
     
        if(!errors.length) {
            refetch({
                method: 'post',
                data: {
                    name: refs.name.current,
                    description: refs.description.current,
                    members: [
                        userId,
                        ...(usersRef?.current?.map(user => user._id) || [])
                    ]
                },
                headers: {
                    'Authorization': `Bearer ${token}`
                }
            }).then(() => {
                dispatch(close());
            });

        } else 
            setChecking(errors);
    }

    return (
        <Box 
            sx={{
                flex:1,
                display: 'flex',
                flexDirection: 'column',
                width: 400,
                minHeight: 300,
            }}
        >
            <DialogContent>
                <Box
                    sx={{display: 'flex', justifyContent: 'center'}}
                >
                    <IconButton size="small"
                        onClick={async () => {
                            const [file] = await asyncGetFile({accept: 'images/*'});
                            setFile(file);
                        }}
                    >
                        <Avatar
                            sx={{ width: 80, height: 80}}
                            src={file && URL.createObjectURL(file)}
                        >
                            <Groups2RoundedIcon sx={{ width: 60, height: 60}}/>
                        </Avatar>
                    </IconButton>
                </Box>
                <Typography variant="body2" paragraph componnent="div">
                    <b>Membres</b> : Moi, { usersRef?.current?.map(
                        (user, index, users) => `${user.lname} ${user.mname}`
                        ).join(', ')
                    }
                </Typography>
                <TextFieldController
                    margin="dense"
                    type="text"
                    label="Nom du salon"
                    size="small"
                    fullWidth
                    regExp={/./}
                    checking={!!checking.find(field => field === 'name')}
                    ref={refs.name}
                />
                <TextFieldController
                    label="Description"
                    margin="dense"
                    type="text"
                    size="small"
                    multiline
                    regExp={/./}
                    checking={!!checking.find(field => field === 'description')}
                    fullWidth
                    ref={refs.description}
                />
            </DialogContent>
            <DialogActions>
                <LoadingButton size="small" 
                    onClick={handleCreateRoom} 
                    variant="contained"
                    loading={loading}
                >creer</LoadingButton> 
                <Button 
                    size="small" 
                    onClick={onPrevious} 
                    variant="contained"
                    disabled={loading}
                >precedent</Button> 
                <Button 
                    size="small" 
                    onClick={() => {
                        if(loading)
                            cancel();
                        dispatch(close())
                    }}
                >annuler</Button> 
            </DialogActions>
        </Box>
    )
}

const URL_ROOM = serverPath('api/chat/room/new');