import {
    Box, AppBar,
} from '@mui/material';

import { useRef, useState } from 'react';
import '../../../../../styles/emoji.css';
//import { useSession } from '../../../../../services/globalConfig';
import SendFile from './SendFile';
import SendAudio from './SendAudio';
import SendText from './SendText';




export default function NavRightFooter ({
    sender, 
    localMessages, 
    setLocalMessages
}) {
    const anchorEl = useRef(null);
    const [values, setValues] = useState({
        type: 'text',
        file: null,
    })


    return (
        <Box sx={{width: '100%', display: 'flex'}} ref={anchorEl}>
            <AppBar position="relative" color="default">
                {values.type === 'text' &&
                    <SendText
                        sender={sender}
                        values={values}
                        setValues={setValues}
                    />
                }
                {values.type === 'audio' &&
                    <SendAudio
                        sender={sender}
                        values={values}
                        setValues={setValues}
                    />
                }
                {values.type === 'file' &&
                    <SendFile
                        sender={sender}
                        values={values}
                        setValues={setValues}
                        localMessages={localMessages}
                        setLocalMessages={setLocalMessages}
                    />
                }
            </AppBar>
        </Box>
    )
}