import * as React from 'react';
import { 
    Box, Typography
} from "@mui/material";
import { useSelector } from "react-redux";
import DocsContent from "./DocsContent";
import ImagesContent from "./ImagesContent";
import VideosContent from "./VideosContent";

export default function ArchivesContent () {
    const subApp = useSelector(state => state.censorshipNavRight.value.subApp);
    const censorshipData = useSelector(state => state.censorshipData.value);
    const data = censorshipData[`archives/${subApp}`];

    const uris = {
        validate: 'api/stuff/archives',
        del: 'api/stuff/frozen',
        frozenType: 'ressource',
    };

    return (
        <Box
            sx={{display: 'flex', flex: 1}}
        >
            {data?.length === 0 ?
           (<Box
                sx={{
                    display: 'flex', 
                    flex: 1,
                    justifyContent: 'center',
                    alignItems: 'center',
                }}
           >
              <Typography variant='body2' color="text.secondary" align="center">Aucun élement trouvé</Typography>  
           </Box>) :
            (<React.Fragment>
                {subApp === 'documents' &&  <DocsContent uris={uris} data={data}/>}
                {subApp === 'images' &&  <ImagesContent uris={uris} data={data}/>}
                {subApp === 'videos' &&  <VideosContent uris={uris} data={data}/>}
            </React.Fragment>)   
            }
            
        </Box>     
    );
}