import React,{ useRef, useState } from 'react';
import {
    Box,
    Typography,
    CardMedia,
    MenuItem,
    Zoom,
    FormControlLabel,
    Checkbox,
} from '@mui/material';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import CropText from './CropText';
import MenuOptions from './MenuOptions';
import FormInputTheme from '../config/FormInputTheme';

export default function VideoPlan (props) {
    const { image, src, label } = props;
    const [selected, setSelected] = useState(false);
    const [showMenu, setShowMenu] = useState(false);
    const [contextMenu, setContextMenu] = useState(null);
    const aRef = useRef(null);
    return (
        <FormInputTheme>
            <Box
                sx={{
                    position: 'relative',
                    width: '100%',
                    height: '100%',
                    top: 0,
                    left: 0,
                    zIndex: 100,
                }}
                onContextMenu={event => {
                    event.preventDefault();
                    setContextMenu(
                        contextMenu === null
                        ? {
                            mouseX: event.clientX + 2,
                            mouseY: event.clientY - 6,
                            }
                        : null,
                    );
                }}
                onMouseEnter={() => setShowMenu(true)}
                onMouseLeave={() => setShowMenu(false)}
            >
                <Zoom in={showMenu}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={selected}
                                onChange={() => {
                                    const newVal = !selected;
                                    setSelected(newVal);
                                    if(typeof props.onSelected === 'function')
                                        props.onSelected(newVal, newVal && props.infos);
                                }}
                                sx={{
                                    color: theme =>  theme
                                    .palette.mode === 'dark' ?
                                    '#0095C9' : theme.palette
                                    .primary.main
                                }}
                            />
                        }
                        sx={{
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            zIndex: 102,
                        }}
                    />
                </Zoom>
                <MenuItem
                    sx={{
                        height: '100%',
                        width: '100%',
                        position: 'absolute',
                        px: 1,
                        py: 0,
                        zIndex: 100,
                    }}
                    selected={selected}
                    onClick={() => aRef.current.click()}
                    component="div"
                />
                <CardMedia
                    component="video"
                    image={image || src}
                    src={src}
                    height={150}
                />
                <Box
                    sx={{
                        position: 'absolute',
                        height: 150,
                        width: '100%',
                        top: 0,
                        left: 0,
                    }}
                >
                    <PlayArrowRoundedIcon
                        fontSize="large"
                        sx={{
                            position: 'absolute',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            color: 'white',
                        }}
                    />
                </Box>
                <a
                    ref={aRef}
                    target="_blank"
                    onClick={props.action}
                    href={props.link || src}
                    rel="noreferrer"
                    hidden
                />
                <Typography
                    variant="caption"
                    color="text.secondary"
                >{label?.length > 40 ?
                    <CropText len={36}>
                        {label}
                    </CropText> : label
                }</Typography>
            </Box>
            <MenuOptions
                options={props.options}
                open={contextMenu !== null}
                onClose={() => {
                    setContextMenu(null);
                  }}
                anchorReference="anchorPosition"
                anchorPosition={
                  contextMenu !== null
                    ? { top: contextMenu.mouseY, left: contextMenu.mouseX }
                    : undefined
                }
            />
        </FormInputTheme>
    )
}
