import * as React from 'react';
import { styled, alpha } from '@mui/material/styles';
import InputBase from '@mui/material/InputBase';

const Wrapper = styled('div')(({ theme }) => ({
  position: 'relative',
  display: 'flex',
  borderRadius: theme.shape.borderRadius,
  backgroundColor: theme.palette.mode === 'dark' ? 
  alpha( theme.palette.common.black, .4) : 
  alpha(theme.palette.common.white, .95),
  '&:hover': {
    backgroundColor: theme.palette.mode === 'dark' ? 
    alpha( theme.palette.common.black, .45) : 
    alpha(theme.palette.common.white, 1),
  },
  marginLeft: 0,
}));

const StyledInputBase = styled(InputBase)(({ theme }) => ({
  color: 'inherit',
  width: '100%',
  '& .MuiInputBase-input': {
    padding: theme.spacing(.5, .5, .5, 0),
    // vertical padding + font size from searchIcon
    paddingLeft: `calc(1em + ${theme.spacing(1)})`,
    paddingRight: `calc(1em + ${theme.spacing(1)})`,
  },
}));



const MultiLineInput = React.forwardRef(({
  value, 
  defaultValue, 
  onChange,
  onKeyDown,
  onKeyPress,
  onKeyUp,
  ...props
}, ref) => {
    return (
        <Wrapper {...props}>
            <StyledInputBase
                placeholder="Tapez votre message…"
                inputProps={{ 'aria-label': 'message', }}
                value={value}
                defaultValue={defaultValue}
                onChange={onChange}
                onKeyDown={onKeyDown}
                onKeyPress={onKeyPress}
                onKeyUp={onKeyUp}
                inputRef={ref}
                maxRows={3}
                multiline
            />
        </Wrapper>
    )
});

MultiLineInput.defaultProps = {

}
export default MultiLineInput;