export const routeDisp = route => {
    let subRoutes = [];
    let { route: path } = route;
    path = path.trim();
    path = path?.charAt(path.length - 1) === '/' ? path.slice(0, path.length - 1) : path;
    if(Array.isArray(route?.subRoutes))
        subRoutes = route.subRoutes;
    subRoutes.forEach(sr => {
        if(sr?.subRoutes?.length)
            subRoutes.push(sr.subRoutes.map(eachSr => routeDisp({
                ...eachSr,
                route: `${path}/${
                    eachSr?.route?.trim()?.charAt(0) === '/' ? eachSr.route?.trim()?.slice(0, path.length) : eachSr.route.trim()
                }`
            })))
    });
    const Element = route?.module;
    const CoverPage = route?.coverPage;

    return (
        <React.Fragment>
            <Route
                path={path}
                element={
                    CoverPage ?
                    <Suspense fallback={<CoverPage/>}>
                        <Element/>
                    </Suspense> : 
                    <Element/>
                }
            />
            {subRoutes}
        </React.Fragment>
    );
}

export default routes;
