import { keyWord, encrypt, decrypt } from "./crypt";

export const parse = data => {
    try {
        return data ?
        (typeof data === 'string') ?
        JSON.parse(data) :
        JSON.stringify(data) : null;
    }
    catch (error) { return null };
};

export const get = type => {
    const localStorageData = parse(decrypt(window.localStorage.getItem(keyWord)));
    const sessionStorageData = parse(decrypt(window.sessionStorage.getItem(keyWord)));
    const defaultValue = {
        cookie: null,
    };
    const init = {
        local: {
            ...defaultValue,
            ...(localStorageData || {}),
        },
        session: sessionStorageData ? sessionStorageData : null
    }
    return type === 'session' ?
        sessionStorageData :
        ( type === 'local' ? localStorageData : init );
};

export const set = (type, data) => {
    if(type === 'object')
        Object.keys(type).forEach((subType) => {
            const storage = get(subType);
            if(window[subType + 'Storage'])
                window[subType + 'Storage']
                .setItem(
                    keyWord,
                    encrypt(
                        parse(
                            storage ? {...storage, ...type[subType]} :
                            type[subType]
                        )
                    )
                );
        });
    else {
        const storage = get(type);
        window[type + 'Storage'].setItem(
            keyWord,
            encrypt(parse(storage ? {...storage, ...data} : data))
            );
    }
};

export const del = type => {
    if(type)
        window[type + 'Storage'].clear(keyWord);
    else {
        window.sessionStorage.clear(keyWord);
        window.localStorage.clear(keyWord);
    }
};

const localStorageData = {del, get, set, parse};
export default localStorageData;
