import {
    ImageListItem,
    ImageListItemBar,
    MenuItem,
    Zoom,
    FormControlLabel,
    Checkbox,
    CardMedia,
} from '@mui/material';
import React,{ useState, useRef } from 'react';
import FormInputTheme from '../config/FormInputTheme';
import MenuOptions from './MenuOptions';
export default function ImagePlan (props) {
    const {src, srcSet, label, ImageListItemBarProps } = props;
    const [selected, setSelected] = useState(false);
    const [showMenu, setShowMenu] = useState(false);
    const [contextMenu, setContextMenu] = useState(null);
    const aRef = useRef(null);

    return (
        <FormInputTheme>
            <ImageListItem
                sx={{
                    position: 'relative',
                    width: '100%',
                    height: '100%',
                    top: 0,
                    left: 0,
                }}
                onContextMenu={event => {
                    event.preventDefault();
                    setContextMenu(
                        contextMenu === null
                        ? {
                            mouseX: event.clientX + 2,
                            mouseY: event.clientY - 6,
                            }
                        : null,
                    );
                }}
                onMouseEnter={() => setShowMenu(true)}
                onMouseLeave={() => setShowMenu(false)}
            >
                <Zoom in={showMenu}>
                    <FormControlLabel
                        control={
                            <Checkbox
                                checked={selected}
                                onChange={() => {
                                    const newVal = !selected;
                                    setSelected(newVal);
                                    if(typeof props.onSelected === 'function')
                                        props.onSelected(newVal, newVal && props.infos);
                                }}
                                sx={{
                                    color: theme =>  theme
                                    .palette.mode === 'dark' ?
                                    '#0095C9' : theme.palette
                                    .primary.main
                                }}
                            />
                        }
                        sx={{
                            position: 'absolute',
                            top: 0,
                            left: 0,
                            zIndex: 102,
                        }}
                    />
                </Zoom>
                <MenuItem
                    sx={{
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        zIndex: 100,
                        height: '100%',
                        width: '100%',
                        dislpay: 'flex',
                    }}
                    selected={selected}
                    onClick={() => aRef.current.click()}
                    component="div"
                >
                </MenuItem>
                <CardMedia
                    component="img"
                    image={src}
                    srcSet={srcSet || src}
                    alt={label.length > 25 ? label.slice(0, 23) + '...' : label}
                    loading="lazy"
                    height={165}
                />
                <ImageListItemBar
                    title={label}
                    {...ImageListItemBarProps || {}}
                    //subtitle={item.author}
                />
            </ImageListItem>
            <a
                target="_blank"
                href={src}
                ref={aRef}
                rel="noreferrer"
                hidden
            />
            <MenuOptions
                options={props.options}
                open={contextMenu !== null}
                onClose={() => {
                    setContextMenu(null);
                  }}
                anchorReference="anchorPosition"
                anchorPosition={
                  contextMenu !== null
                    ? { top: contextMenu.mouseY, left: contextMenu.mouseX }
                    : undefined
                }
            />
        </FormInputTheme>
    )
}

ImagePlan.defaultProps = {
    label: '',
};
