function FilesNav () {
  const [workspacesValues, handleChange] = useContext(WorkspacesProps);
  const [,{getSession}] = useSession();
  const [{loading}, refetch,] = useAxios(WORKSPACE_GET_DATA_URL, { manual: true});
  const [values, setValues] = useState({
    navigation: 'documents'
  });
  const defaultFolders = [
      {label: 'Documents', src: folderDocImgIcon, value: 'documents'},
      {label: 'Images', src: folderPhotoImgIcon, value: 'images'},
      {label: 'Videos', src: folderVideoImgIcon, value: 'videos'},
      {label: 'autre', src: folderOtherImgIcon, value: 'others'}
  ];
  const handleGetData = () => {
    const {id, token, } = getSession('user');
    const path = values.navigation;
    if(workspacesValues.currentTab.current !== path) {
      workspacesValues.currentTab.current = path;
      const updateData = handleChange({
        data: {
          ...workspacesValues.data,
        }
      });
      updateData(null);
    }
    const authUserInfo = localStorageData.parse({
      userId: id, path: values.navigation === 'others' ? 'documents' : values.navigation
    });
    refetch({
      url: WORKSPACE_GET_DATA_URL + authUserInfo,
      headers: {
        'Authorization': `Bearer ${token}`
      },
    }).then(result => {
      const oldData = workspacesValues.data[path];
      const newData = result.data;
      if(localStorageData.parse(oldData) !== localStorageData.parse(newData)) {
        const others = [];
        const documents = [];
        newData.forEach(item => {
            const isOther = !fileExtensionBase
            .find(extItem => ~extItem.exts.indexOf(getFileExtension(item.name)));
            if(isOther) others.push(item);
            else documents.push(item);
        });
        const updateData = handleChange({
          data: {
            ...workspacesValues.data,
            [path]:  newData,
            others,
            ...(path === 'documents' ? {documents} : {}),
          },
          refetch: handleGetData,
        });
        updateData(null);
      }
    });
  }
  useEffect(handleGetData, [values.navigation]);
  // console.log(workspacesValues.data);
  return (
    <React.Fragment>
        <List
          dense={false}
          sx={{
            m:1,
            overflow: 'hidden', 
          }}
          subheader={
            <Typography
              variant="h6"
              fontSize={18}
            >
            Fichier
            </Typography>
          }
        >
        {defaultFolders.map((folder, index) => (
          <ListItemButton
              key={index}
              dense={false}
              selected={folder.value === values.navigation}
              onClick={() => setValues({...values, navigation: folder.value})}
          >
              <ListItemIcon>
                <ImgToIcon
                  src={folder.src}
                  size={25}
                />
              </ListItemIcon>
              <ListItemText
                primary={folder.label}
                primaryTypographyProps={{
                  fontSize: 14,
                  height: 18,
                }}
              />
          </ListItemButton>
          ))}
        </List>
      {
      <Backdrop
        sx={{
          color: '#fff',
          zIndex: (theme) => theme.zIndex.appBar + 10,

          backdropFilter: 'blur(15px)',
        }}
        open={
          !workspacesValues.data[
            workspacesValues.currentTab.current
            ].length && loading
        }
      >
        <CircularProgress
          color="inherit"
           size="small"
           sx={{
             width: 25,
             height: 25
           }}
        />
      </Backdrop>
        }
    </React.Fragment>
  )
}

function FastNavApp () {
  return (
    <Box>
      <Typography sx={{m: 1}} variant="h6" fontSize={18}>
                Applications
        </Typography>
        <Box
            sx={{
                display: 'flex',
                flex: 1,
                width: 300,
                m: 1,
                flexDirection: 'row',
                height: 350,
            }}
            component={Grid}
            container
        >
            {apps.sort().map((app, index) => (
                <Box
                    component={Grid}
                    item
                    key={index}
                    xs={3}
                >
                    <Stack spacing={.1}>
                        <CardActionArea
                            sx={{
                                display: 'flex',
                                justifyContent: 'center',
                                alignItems: 'center',
                                p: .5,
                            }}
                            LinkComponent={Link}
                            to={app.path}
                        >
                            <ImgToIcon
                                src={app.icon}
                                size={50}
                            />
                        </CardActionArea>
                        <FormHelperText
                            sx={{textAlign: 'center', textOverflow: 'ellipsis',}}
                        >{
                        app.label.length <= 10 ? app.label :
                        <CropText
                            len={7}
                            padType="left"
                        >{app.label}</CropText>
                        }</FormHelperText>
                    </Stack>
                </Box>
            ))}
        </Box>
    </Box>
  )
}

