import * as React from 'react';
import { 
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
} from '@mui/material';
import { useDispatch, useSelector } from 'react-redux';
import FastContacts from './FastContacts';
import { useSession } from '../../../services/globalConfig';
import { addContact } from '../../../redux/apps/livingroom/contacts';
import CreateRoom from './CreateRoom';
import LoadingList from '../component/LoadingList';
import { close } from '../../../redux/apps/livingroom/fastContactNav';

const Content = ({mode}) => {
  const contacts = useSelector(state => state.contacts.value);
  const [tab, setTab] = React.useState(0);
  const selectUsers = React.useRef([]);
  const [{socket},] = useSession();
  const dispatch = useDispatch();

  React.useEffect(() => {
    if(!contacts)
        socket?.emit('contacts');
    socket.on('contacts', data => {
        const { contacts } = data;
        dispatch(addContact(contacts));
    });
}, [socket, contacts]);
  return (
    <React.Fragment>
      <DialogTitle>
        {tab ? 'Création du Salon' : 'Contacts'}
      </DialogTitle>
        {
        !contacts ?
          (
          <React.Fragment>
            <DialogContent sx={{width: 400}}>
              <LoadingList
                loading={!contacts}
                nbrList={5}
            />
            </DialogContent>
            <DialogActions>
              <Button
                size="small"
                onClick={() => {
                  dispatch(close());
                }}
              >annuler</Button>
            </DialogActions>
          </React.Fragment>): 
        (<React.Fragment>
          {tab === 0 && 
          <FastContacts
            mode={mode} 
            users={contacts} 
            usersRef={selectUsers}
            onNext={() => setTab(1)} 
          />}
          {tab === 1 && 
          <CreateRoom 
            usersRef={selectUsers} 
            onPrevious={() => setTab(0)} 
          />}
        </React.Fragment>)
        }
    </React.Fragment>
  )
}

export default function FastListContacts (props) {
    const nav = useSelector(state => state.fastContactNav.value);

    return (
        <Dialog 
          open={nav.open}  
          aria-labelledby="contacts"
          BackdropProps={{
            sx: {
              backdropFilter: 'blur(15px)'
            }
          }}
        >
          <Content
            mode={nav.mode}
          />
        </Dialog>
    );
}
