import * as React from 'react'
import {
  Avatar,
  BottomNavigation,
  BottomNavigationAction,
  Box,
  IconButton,
  ListItemAvatar,
  Tooltip,
  Badge
} from '@mui/material';
import AppBar from '@mui/material/AppBar'
import Toolbar from '@mui/material/Toolbar'
import Typography from '@mui/material/Typography'
import CustomBadge from '../../component/StyledBadge'
import { useDispatch, useSelector } from 'react-redux';
import MenuOptions from '../../../../components/MenuOptions';
import fastOption from '../options/fastOptions';
import navigationButtons from '../options/navigationButtons';
import ResearchBar from './ResearchBar';
import { changeValue } from '../../../../redux/apps/livingroom/currentNavLeft';
import { useNavigate } from 'react-router-dom';
import screenOptions from '../options/screenOptions';


const NavigationOption = props => {
  const nButton = useSelector(state => state.currentNavLeft.value);
  const dispatch = useDispatch();


  return (
    <Box sx={{ my: 2 }}>
      <BottomNavigation
        showLabels
        value={nButton.value}
        onChange={(event, newValue) => {
          dispatch(changeValue(newValue));
        }}
      >
        {navigationButtons.map(btn => (
          <BottomNavigationAction
            key={btn.id}
            label={btn.label}
            value={btn.id}
            disabled={btn.disabled}
            icon={
              <Badge 
                badgeContent={btn.nbr} 
                color="primary"
                sx={{
                  '& .MuiBadge-badge':{
                    border: theme => `1px solid ${theme.palette.background.paper}`
                  } 
                }}
              >
                <btn.icon
                  fontSize="small"
                />
              </Badge>
            }
          />
        ))}
      </BottomNavigation>
    </Box>
  )
}

const AppBarStatus = props => {
  const {
    firstName,
    lastName,
    middleName,
    imageUrl
  } = useSelector(state => state.user.value);
  const [values, setValues] = React.useState({
    anchorEl: null,
    options: [],
  });
  const navigateTo = useNavigate();
  const screen = useSelector(state => state.screen.value);
  const open = Boolean(values.anchorEl);
  
  const nextState =  screen === 'normal' ? 'croped' : screen === 'croped' ? 'full' : 'normal';



  const handleClick = (event, options) => {
    setValues({
      anchorEl: event.currentTarget,
      options,
    });
  };

  return (
    <React.Fragment>
      <AppBar position="sticky" color="default" sx={{boxShadow: 0}}>
        <Toolbar>
          <ListItemAvatar>
            <CustomBadge
              variant="dot"
              overlap="circular"
              anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
            >
              <Avatar
                children={
                  lastName?.charAt(0) +
                  firstName?.charAt(0)
                }
                sx={{fontSize: 15}}
                src={imageUrl}
              />
            </CustomBadge>
          </ListItemAvatar>
          <Box sx={{ flexGrow: 1, ml: 1 }}>
            <Typography 
              component="div" 
              sx={{textOverflow: 'ellipsis', 
              maxWidth: 140, 
              whiteSpace: 'nowrap', 
              overflow: 'hidden',  
              }}
            >
              {lastName} {middleName} {firstName}
            </Typography>
          </Box>
          {fastOption.map((btn, index) => (
            <React.Fragment key={index}>
              <Tooltip 
                title={(() => {
                  const label = btn.id === 'screen' ?
                  screenOptions.find(screen => screen.id === nextState).label :
                  btn.label;
                  return label
                })()} 
                arrow
              >
                <IconButton 
                  size="small" 
                  sx={{ ml: 1 }}
                  onClick={btn.action ? 
                    btn.action([nextState, navigateTo][index]) : 
                    (event => {
                    handleClick(event, btn.options)
                  })}
                >
                {(() => {
                    const Icon = btn.id === 'screen' ?
                     btn.options.find(({id}) => id === nextState).icon :
                     btn.icon;
                    return <Icon fontSize="small" />
                  })()
                }
                </IconButton>
              </Tooltip>
            </React.Fragment>
          ))}
        </Toolbar>
      </AppBar>
      <MenuOptions
        anchorEl={values.anchorEl}
        open={open}
        onClose={() => setValues({
          ...values,
          anchorEl: null,
        })}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'left',
        }}
        options={values.options}
      />
    </React.Fragment>
  )
}

export default function NavLeftHeader() {

  return (
      <Box>
        <AppBarStatus />
        <ResearchBar/>
        <NavigationOption />
      </Box>
  )
}