import {
    Box,
    CircularProgress,
    ListItem,
    ListItemText,
    ListItemIcon,
    Typography,
    IconButton,
    Divider,
} from '@mui/material';
import { useEffect, useState } from 'react';
import CropText from '../../../components/CropText';
import FormInputTheme from '../../../config/FormInputTheme';
import normaliseOctetSize from '../../../services/normaliseOctetSize';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';

export default function UploadProgressStatus (props) {
    const { uploadInfos } = props;
    const {
        loaded,
        total,
        state,
        name,
        timeout,
        target,
        startTime,
        cancel,
    } = uploadInfos;
    const [progress, setProgress] = useState({loaded, total, timeout,});
    const nSizeL = normaliseOctetSize(progress.loaded);
    const nSizeT =  normaliseOctetSize(progress.total);

    useEffect(() => {
        const onProgress = event => {
            const {loaded, total} = event;
            const endTime = new Date().getTime();
            const duration = (endTime - startTime) / 1000;
            const bbs = loaded / duration;
            const timeout = (loaded - total) / bbs;
            setProgress({ loaded, total, timeout});
        };
        target.upload.addEventListener('progress', onProgress);
        return (() => {
            target.upload.removeEventListener('progress', onProgress);
        });
    }, []);
    
    return (
        <FormInputTheme>
           <ListItem sx={{height: 65}}>
                <ListItemIcon>
                    <Box sx={{ position: 'relative', display: 'inline-flex' }}>
                        <CircularProgress variant="determinate"
                            value={
                            Math.max(
                                progress.loaded / progress.total,
                                loaded / total
                            ) * 100}
                        />
                        <Box
                            sx={{
                            top: 0,
                            left: 0,
                            bottom: 0,
                            right: 0,
                            position: 'absolute',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            }}
                        >
                            <Typography
                            variant="caption"
                            component="div"
                            color="text.secondary"
                            >{`${Math.floor(state === 'end' ? 100 : loaded * 100 / total)}%`}
                            </Typography>
                        </Box>
                    </Box>
                </ListItemIcon>
                <ListItemText
                    sx={{flexGrow: 1}}
                    primaryTypographyProps={{
                        fontSize: 15,
                        variant: 'h6',
                        color: 'primary',
                    }}
                    secondaryTypographyProps={{
                        variant: 'caption',
                        fontSize: 10,
                    }}
                    primary={ (name || {}).length > 24 ?
                        <CropText
                            len={22}
                        >{name || 'uploades'}</CropText>:
                        name
                    }
                    secondary={ state === 'start' ?
                        `${nSizeL} sur  ${nSizeT}`:
                        `Téléchargement terminé ${nSizeT}` 
                    }
                />
                <IconButton
                    size="small"
                    onClick={cancel}
                >
                    <CloseRoundedIcon/>
                </IconButton>
            </ListItem>
            <Divider sx={{mb:1}}/>
        </FormInputTheme>
    );
}
