import React, { useContext, useEffect, useRef, useState } from 'react';
import { WorkspacesProps } from '../Workspaces';
import {
    Stack,
    AppBar,
    Toolbar,
    IconButton,
    Typography,
    Button,
    useTheme,
    Box,
    Avatar,
    Tooltip,
    Chip,
    Badge,
    Divider,
} from '@mui/material';
import FormInputTheme from '../../../config/FormInputTheme';
import ArrowDropDownRoundedIcon from '@mui/icons-material/ArrowDropDownRounded';
import UploadFileRoundedIcon from '@mui/icons-material/UploadFileRounded';
import CreateNewFolderRoundedIcon from '@mui/icons-material/CreateNewFolderRounded';
import FullscreenRoundedIcon from '@mui/icons-material/FullscreenRounded';
import FullscreenExitRoundedIcon from '@mui/icons-material/FullscreenExitRounded';
import SettingsRoundedIcon from '@mui/icons-material/SettingsRounded';
import { useConfig, useSession } from '../../../services/globalConfig';
import SearchInput from '../../../components/SearchInput';
import MenuOpenRoundedIcon from '@mui/icons-material/MenuOpenRounded';
import ExitToAppRoundedIcon from '@mui/icons-material/ExitToAppRounded';
import { useNavigate } from 'react-router-dom';
import NoteAddRoundedIcon from '@mui/icons-material/NoteAddRounded';
import MenuOptions from '../../../components/MenuOptions';
import FormFileNav from '../../../components/FormFileNav';
import UploadNav from './UploadNav';
import asyncGetFile from '../../../services/asyncGetFile';

export default function WorkspacesHeader (props) {
    const [,{getSession}] = useSession();
    const { lastName } = getSession('user');
    const [context, handleChange] = useContext(WorkspacesProps);
    const [, actions] = useConfig();
    const navigateTo = useNavigate();
    const [values, setValues] = useState({
        menuAction: false,
        file: null,
        selects: 1,
    });
    const [uploads, setUploads] = useState({
      nbr: 0,
      current: 0,
    });
    const fileData = React.useRef({});
    const theme = useTheme();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    const folderAction = useRef();
    const inputSeach = useRef();
    const handleFullscreenMode = () => {
       if(context.fullScreen)
           document.exitFullscreen()
       else
           document.body.requestFullscreen();
      handleChange('fullScreen', !context.fullScreen)(null);
    };
    useEffect(() => {
        if(context.refetch)
            context.refetch();
    },[uploads]);

    return (
        <React.Fragment>
             <FormInputTheme>
                {values.file &&
                    <FormFileNav
                        file={values.file}
                        onClose={() => setValues({...values, file: null})}
                        labelAction="ajouter"
                        action={(event, file) => {
                            event.preventDefault();
                            fileData.current.file = file;
                            if(fileData.current.el) fileData.current.el.click();
                        }}
                    />}
                <MenuOptions
                    open={values.menuAction}
                    anchorEl={folderAction.current}
                    onClose={() => setValues({...values, menuAction: false })}
                    anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
                    sx={{p:0}}
                />
                <UploadNav
                    ref={fileData}
                    onUploads={(nbr, current) => setUploads({nbr, current})}
                /> 
             </FormInputTheme>
            <AppBar
                position="sticky"
                sx={{
                    backdropFilter: 'blur(15px)',
                    bgcolor: theme => theme.palette.background.paper + 'ee'
                }}
            >
            <Toolbar>
                {!context.openNavLeft &&
                    <IconButton
                        size="small"
                        edge="start"
                        onClick={handleChange('openNavLeft', !context.openNavLeft)}
                    >
                        <MenuOpenRoundedIcon />
                    </IconButton>}
                    <Typography variant="h6" color={color} sx={{mx:1, flexGrow: 1}}>
                        Espace personnel
                    </Typography>
                    <Box>
                        <SearchInput
                            ref={inputSeach}
                            onChange={context.onChange}
                        />
                    </Box>
                    <Box component={Stack} direction="row" spacing={1} sx={{mx: 1}}>
                    <Box>

                        <Tooltip
                           arrow
                           title={
                              uploads.nbr ? `${uploads.nbr} élement${uploads.nbr > 1 ? 's' : ''} sur la liste` +
                              uploads.current ? `${uploads.current}
                              élement${uploads.current > 1 ? 's' : ''} en cours de téléchargement` : ''
                              : 'Liste de Téléchargements, Aucun téléchargement en cours'
                           }
                           enterDelay={700}
                        >
                            <IconButton size="small"
                                onClick={() => fileData.current.el.click()}
                            >
                                <Badge
                                    color="primary"
                                    badgeContent={uploads.nbr}
                                >
                                    <UploadFileRoundedIcon fontSize="small"/>
                                </Badge>
                            </IconButton>
                        </Tooltip>
                        </Box>

                        <Box>
                            <Tooltip arrow title="Plein écran" enterDelay={700} >
                                <IconButton size="small"
                                    onClick={handleFullscreenMode}
                                >
                                    {context.fullScreen ?
                                    <FullscreenExitRoundedIcon fontSize="small"/> : <FullscreenRoundedIcon fontSize="small"/>}
                                </IconButton>
                            </Tooltip>
                        </Box>
                        <Box>
                            <Tooltip arrow title="Paramètre" enterDelay={700}>
                                <IconButton size="small"
                                    onClick={() => actions(null).handleChangeProps({settingsNav: true})}
                                >
                                    <SettingsRoundedIcon fontSize="small"/>
                                </IconButton>
                            </Tooltip>
                        </Box>
                        <Box>
                            <Tooltip arrow title="sortir" enterDelay={700}>
                                <IconButton
                                    size="small"
                                    onClick={() => {
                                        navigateTo('/home');
                                    }}
                                >
                                    <ExitToAppRoundedIcon fontSize="small"/>
                                </IconButton>
                            </Tooltip>
                        </Box>
                        <Box>
                            <Tooltip arrow title="Profil" enterDelay={700}>
                                <Chip avatar={<Avatar />} label={lastName} variant="outlined"
                                />
                            </Tooltip>
                        </Box>
                    </Box>
            </Toolbar>
            </AppBar>
            <Stack direction="row" spacing={1} margin={1} sx={{bgcolor: 'background.paper', p: 1}} >
                    <Button
                         variant="outlined"
                         color={color}
                         size="small"
                         sx={{textTransform: 'none'}}
                         onClick={async () => {
                            const [ file ] = await asyncGetFile();
                            setValues({...values, file : file || null});
                         }}
                         startIcon={
                             <NoteAddRoundedIcon/>
                         }
                    >
                        Ajouter un fichier
                    </Button>
                    <Button
                         variant="outlined"
                         size="small"
                         color={color}
                         disabled={true}
                         sx={{textTransform: 'none'}}
                         startIcon={
                             <CreateNewFolderRoundedIcon/>
                         }
                    >
                        Nouveau dossier
                    </Button>
                    <Button
                        variant="outlined"
                        color={color}
                        sx={{textTransform: 'none'}}
                        size="small"
                        ref={folderAction}
                        onClick={() => setValues({...values, menuAction: true })}
                        endIcon={
                            <ArrowDropDownRoundedIcon/>
                        }
                        disabled={true}
                    >
                        Action sur le dossier
                    </Button>
                    <Divider sx={{flexGrow: 1}}/>
                    <Button
                        variant="outlined"
                        color={color}
                        sx={{textTransform: 'none'}}
                        size="small"
                        ref={folderAction}
                        disabled
                    >
                        sélectionner
                    </Button>
            </Stack>
        </React.Fragment>
    )
}
