import { Box, CardMedia, ImageList, ImageListItem, ImageListItemBar } from "@mui/material";
import { useSelector } from "react-redux";
import ImagePlan from "../../../../components/ImagePlan";
import FileWrapper from "../../components/FileWrapper";

const ImageItem = ({file, uris}) => {
    const { fileUrl:src, title, description } = file;
    return (
        <FileWrapper file={file} uris={uris}>
            <ImageListItem
                height={165}
                sx={{display: 'block'}}
            >
                <CardMedia
                    component="img"
                    sx={{overflow: 'hidden'}}
                    image={src}
                    srcSet={src}
                    alt={description}
                    loading="lazy"
                    height={165}
                />
                <ImageListItemBar
                    title={title}
                    //subtitle={item.author}
                />
            </ImageListItem>
        </FileWrapper>
    )
}

export default function ImagesContent ({data, uris}) {
    const isSmall = useSelector(state => state.censorshipNavLeft.value.open);
    return (
        <Box
           sx={{
            display: 'flex',
            flex: 1,
           }} 
        > 
        <Box>
                {!!data?.length &&
                <ImageList
                    cols={ isSmall ? 4 : 6}
                    sx={{
                        m: 1, 
                    }}
                >
                    {data?.map((image, index) => (
                        <ImageItem
                            key={index}
                            file={image}
                            uris={uris}
                        />
                    ))
                    }
                </ImageList>}
        </Box>
        </Box>
    );
}