export default function FormSend (props) {
    const [{loading, error}, refecth, cancel] = useAxios(SEND_URL, {manual: true});
    const [,{getSession}] = useSession();
    const [values, setValues] = useState({
        checking: [],
        coverNav: false,
        coverURL: null,
        snackOpen: false,
    });
    const type = useRef(fileExtensionBase.find(
        type => ~type.exts
        .indexOf(getFileExtension(props?.file?.name))
    )?.type || {});
    
    const data = {
        desc: useRef(''),
        desi: useRef(''),
        type: useRef(''),
        object: useRef(''),
        title: useRef(''),
        author: useRef(''),
        doc: useRef(''),
        subDoc: useRef(''),
        cover: useRef(''),
    };

    const subApp = props.app ? (subApps[props.app] || {})[type.current] : '';

    const handleSend = event => {
        event?.preventDefault();
        const {id: userId, token, } = getSession('user');
        let fieldsError = [];
        const fileData = {};
        [   
        ...(props.app === 'archives' ? fieldsChicking[props.app] :
            fieldsChicking[props.app][
                type !== 'document' ? 'other' : type 
            ])
        ].forEach(field => {
            console.log(field);
            if (!data[field]?.current)
                fieldsError.push(field);
            if (field === 'subDoc') 
                fieldsError = data[field]?.current === null ? 
                fieldsError.map(field => field !== 'subDoc' && field)
                .filter(field => field) : fieldsError;
        });
        if (type.current === 'document') {
            if (data.cover.current)
             fileData.coverName = data?.cover?.current?.name
            else fieldsError.push('cover');
        } 
        
        Object.keys(data).forEach(key =>  data[key]?.current && (fileData[key] = data[key]?.current ));
        if(fieldsError.length) 
            setValues({
                ...values, 
                checking: fieldsError
            });
        else {
            Object.keys(data).forEach(field => {
                if(!data[field]?.current)
                    delete data[field]
            })
    
            const fields = {
                    userId,
                    where: `${
                        typeof type.current === 'object' ? 
                        'document' : type.current
                    }s/${props?.file?.name}`,
                    datas: {
                        frozenType: props.app === 'archives' ?
                        'ressource' : {video: 'film', document: 'book', image: 'image'}
                        [type.current],
                        ...refStructObj(
                            fileData,   {
                            desc: 'description',
                            desi: 'designation',
                        }),
                        ...{doc: undefined, subDoc: undefined},
                        ...props.app === 'archives' ? {
                        type: {
                            type: data.doc?.current,
                            subtype: data.subDoc?.current,
                        }} : {}
                    }
            };
            refecth({
                data: fields, method: 'post',
                headers: { 'Authorization': `Bearer ${token}`, },  
            }).then(() => {
                setValues({
                    ...values, 
                    checking: [],
                    snackOpen: true,
                });
                props?.onClose();
            }).catch(error => {
                setValues({...values, snackOpen: true});
                props?.onClose();
            });
        }
    };
    return (
        <Fragment>
            <FormInputTheme>
                <Dialog
                    open={props.open}
                    BackdropProps={{
                        sx:{
                            backdropFilter: 'blur(15px)', 
                        }
                    }}
                    onKeyDown={event => event.keyCode === 13 && handleSend(event)}
                >
                    <DialogTitle>
                        <Typography fontSize={18} sx={{flexGrow:1}} variant="h6" component="div">
                            Envoyer vers {props?.title?.toLowerCase()} {props.app === 'medialibrary' && `(${subApp})`}
                        </Typography>
                    </DialogTitle>
                    <DialogContent>
                        <Grid container spacing={1}>
                            {props.app === 'medialibrary' && 
                            <MediaLibraryContent
                                refs={{
                                    type: data.type,
                                    object: data.object,
                                    title: data.title ,
                                    author: data.author,
                                }}
                                type={type.current}
                                checking={values.checking}
                            />}
                            {props.app === 'archives' && 
                            <ArchivesContent
                                refs={{
                                    desi: data.desi  ,
                                    type: data.type,
                                    object: data.object,
                                    doc: data.doc,
                                    subDoc: data.subDoc,
                                }}
                                type={type.current}
                                checking={values.checking}
                            />}
                            <Grid item sx={{flexGrow: 1}}>
                                <TextFieldController
                                    id="description"
                                    label="Description"
                                    type="text"
                                    size="small"
                                    fullWidth
                                    margin="dense"
                                    regExp={/\w/}
                                    inputProps={{
                                        multiline: true,
                                        rows: 6
                                    }}
                                    checking={!!~values.checking.indexOf('desc')}
                                    ref={data.desc}
                                />
                            </Grid>
                            {type.current === 'document' &&
                                <Grid item>
                                    <CoverContent
                                        open={values.coverNav}
                                        src={values.coverURL}
                                        error={!!~values.checking.indexOf('cover')}
                                        onClose={(val = null) => () => 
                                            setValues({
                                                ...values, 
                                                coverNav: val === null ? false : val
                                            })}
                                        onChange={cover => {
                                            const { coverURL } = cover;
                                            setValues({
                                            ...values, 
                                                coverURL,
                                                coverNav: false,
                                            })
                                            data.cover.current = cover;
                                        }}
                                    />
                                </Grid>}
                        </Grid>
                    </DialogContent>
                    <DialogActions>
                        <Button
                            children="annuler"
                            size="small"
                            onClick={() => {
                                cancel();
                                props?.onClose();
                            }}
                        />
                        <LoadingButton
                            children="envoyer"
                            size="small"
                            variant="outlined"
                            onClick={handleSend}
                            loading={loading}
                        />
                    </DialogActions>
                </Dialog>
            </FormInputTheme>
            <Snackbar
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'center'
                }}
                onClose={() => setValues({...values, snackOpen: false})}
                open={values.snackOpen}
                autoHideDuration={8000}
            >
                <Alert
                     severity={error ? 'error' : 'success'}
                     action={
                        <IconButton size="small"
                        onClick={() => setValues({...values, snackOpen: false})}
                        >
                            <CloseRoundedIcon/>
                        </IconButton>
                     }
                >
                    <AlertTitle>
                        {props?.file?.name?.length < 40 ?
                        props?.file?.name :
                        <CropText len={40}>{props?.file?.name}</CropText>
                    }
                    </AlertTitle>
                    <FormHelperText>
                        {error ? `
                        Impossible d'envoyer ce fichier, une erreur est survenue lors du transfère
                        `:`
                         Le fichier envoyé avec succès
                        `}
                    </FormHelperText>
                </Alert>
            </Snackbar>
        </Fragment>
    )
}

