import * as React from "react";
import { styled } from '@mui/material/styles';
import ArrowForwardIosSharpIcon from '@mui/icons-material/ArrowForwardIosSharp';
import MuiAccordion from '@mui/material/Accordion';
import MuiAccordionSummary from '@mui/material/AccordionSummary';
import MuiAccordionDetails from '@mui/material/AccordionDetails';
import { 
    List,
    Typography 
} from "@mui/material";
import ExpandMoreRoundedIcon from '@mui/icons-material/ExpandMoreRounded';
import ContactInvitationItem from "../../component/ContactInvitationItem";
import { useSelector } from "react-redux";
import useAxios from "axios-hooks";
import serverPath from "../../../../services/serverPath";

const Accordion = styled((props) => (
    <MuiAccordion disableGutters elevation={0} square {...props} />
  ))(({ theme }) => ({
    border: `1px solid ${theme.palette.divider}`,
    '&:not(:last-child)': {
      borderBottom: 0,
    },
    '&:before': {
      display: 'none',
    },
  }));
  
  const AccordionSummary = styled((props) => (
    <MuiAccordionSummary
      expandIcon={<ArrowForwardIosSharpIcon sx={{ fontSize: '0.9rem' }} />}
      {...props}
    />
  ))(({ theme }) => ({
    backgroundColor:
      theme.palette.mode === 'dark'
        ? 'rgba(255, 255, 255, .05)'
        : 'rgba(0, 0, 0, .03)',
    flexDirection: 'row-reverse',
    '& .MuiAccordionSummary-expandIconWrapper.Mui-expanded': {
      transform: 'rotate(90deg)',
    },
    '& .MuiAccordionSummary-content': {
      marginLeft: theme.spacing(1),
    },
  }));
  
  const AccordionDetails = styled(MuiAccordionDetails)(({ theme }) => ({
    padding: theme.spacing(2),
    borderTop: '1px solid rgba(0, 0, 0, .125)',
    margin: 0,
    padding: 0,
  }));

const ContactInvitationItemFragment = ({divider, message, id}) => {
    const [{loading: loadingAccept,}, onAccept] = useAxios(ACCEPT_URL,{ manual: true});
    const [{loading: loadingRefuse,}, onRefuse] = useAxios(REFUSE_URL,{ manual: true});
    const token = useSelector(state => state.user.value.token);

    return (
      <ContactInvitationItem
          divider={divider}
          message={message}
          onAccept={() => {
            onAccept({
              data: {
                 _id: id
              },
              method: 'post',
              headers: {
                'Authorization': `Bearer ${token}`
              }
            })
          }}
          onRefuse={() => {
            onRefuse({
              data: {
                 _id: id
              },
              method: 'post',
              headers: {
                'Authorization': `Bearer ${token}`
              }
            })
          }}
          loadingAccept={loadingAccept}
          loadingRefuse={loadingRefuse}
      />
    );
}

export default function InvitationList () {
    const { nbr, invitations } = useSelector(state => state.notifications.value);
    
    return (
    <React.Fragment>
        <Accordion elevation={0}>
            <AccordionSummary
             expandIcon={<ExpandMoreRoundedIcon />}
             sx={{py: 0, my: 0}}
            >
                <Typography>Invitations</Typography>
            </AccordionSummary>
            <AccordionDetails sx={{py: 0, my: 0}}>
                <List>
                    {invitations.map((invitation, index, invitations) => (
                      <ContactInvitationItemFragment
                        key={index}
                        divider={(invitations.length - 1) !== index}
                        message={(() => {
                          const { lname, mname, fname} = invitation.from;
                          return `${lname} ${mname} ${fname}`
                        })()}
                        id={invitation._id}
                      />
                    ))}
                </List>
            </AccordionDetails>
        </Accordion>
    </React.Fragment>
    )
}

const ACCEPT_URL = serverPath('api/chat/accept');
const REFUSE_URL = serverPath('api/chat/reject');