import * as React from "react";
import { Box, Slide, Typography, } from "@mui/material";
import { useSelector } from "react-redux";
import ContactsList from "./ContactsList";
import Notifications from "./Notifications";
import TalkinList from "./TalkingList";

const panels = [
    {
        content: <ContactsList/>,
        value: 'contacts',
    },
    {
        content: <TalkinList/>,
        value: 'chats',
    },
    {
        content: <Notifications/>,
        value: 'news',
    },
];
const Panel = ({show, children}) => (
    <Slide
        style={{
            dlsplay: 'flex',
            position: 'absolute',
            height: 'calc(100% - 60px)'
        }}
        in={show}
        direction="right"
    >
        <Box 
            sx={{ 
                display: 'flex', 
                flexDirection: 'column', 
                flex: 1, 
                width: '100%', 
                overflow: 'hidden',
            }}
        >
        {children}
        </Box>
    </Slide>
);

export default function NavLeftContent () {
    const list = useSelector(state => state.currentNavLeft.value);

    return (
        <Box
            sx={{
                display: 'flex', 
                flex: 1,
                flexDirection: 'column',
                position: 'relative',
                overflow: 'hidden',
                
            }}
        >
        {
        panels.map((panel, index) => (
            <Panel
                key={index}
                show={panel.value === list.value}
            >
                {panel.content}
            </Panel>
        ))
        }
        <Box
            sx={{
                display: 'flex', 
                flex: 1,
                flexDirection: 'column',
                position: 'absolute',
                bottom: 0,
                width: '100%',
            }}
        >
            <Typography align="center" paragraph variant="caption" color="text.secondary">
                DANTIC &copy;2022
            </Typography>
        </Box>
        </Box>
    );
}