import * as React from 'react';
import {
    Box,
    Divider,
    Drawer, 
    List, 
    ListItemButton,
    Typography,
    ListItemAvatar,
    ListItemText,
    ListItemIcon,
    Radio,
    Avatar,
    ListSubheader,
    IconButton,
    ListItem
} from '@mui/material';
import LightModeRoundedIcon from '@mui/icons-material/LightModeRounded';
import NightlightRoundRoundedIcon from '@mui/icons-material/NightlightRoundRounded';
import Brightness4RoundedIcon from '@mui/icons-material/Brightness4Rounded';
import FormInputTheme from '../config/FormInputTheme';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import { useConfig } from '../services/globalConfig';
import { useDispatch, useSelector } from 'react-redux';
import { switchTheme } from '../redux/theme';
const optionsTheme = [
      {label: 'Clair', icon: LightModeRoundedIcon, value: 'light'},
      {label: 'Sombre', icon: NightlightRoundRoundedIcon, value: 'dark'},
      {label: 'Thème par défaut du système', icon: Brightness4RoundedIcon, value: 'system'}
  ];
export default function SettingsNav (props) {
    const [{settingsNav}, actions] = useConfig();
    const themeMode = useSelector(state => state.theme.value);
    const dispatch = useDispatch();

    return (
        <Drawer
          anchor="right"
          open={settingsNav}
          onClose={() => actions(null).handleChangeProps({settingsNav: false})}
          {...props}
          BackdropProps={{
            sx:{backdropFilter: 'blur(15px)',}
          }}
        >
          <Box
            sx={{width: 300, p:1}}
          >
              <Box sx={{justifyContent: 'right', display: 'flex'}}>
                <IconButton
                  size="small"
                  onClick={() => actions(null).handleChangeProps({settingsNav: false})}
                >
                  <CloseRoundedIcon/>
                </IconButton>
              </Box>
            <Typography 
              variant="h6"
              fontSize={20}
            >
              Paramètre
            </Typography>
            <Divider/>
            <Box>
            <FormInputTheme>
              <List 
                dense={false}
                sx={{mt: 1}}
                subheader={
                  <ListSubheader component="div">
                    Apparence
                  </ListSubheader>
                }
              >
                {
                  optionsTheme.map((theme, index) => (
                    <ListItem 
                      key={index}
                      secondaryAction={
                        <ListItemAvatar>
                          <Avatar
                            sx={{ 
                              width: 30, 
                              height: 30, 
                              bgcolor: theme.value === themeMode ? 
                              'primary.main': ''
                            }}
                          >
                            <theme.icon/>
                          </Avatar>
                        </ListItemAvatar>
                      }
                      disablePadding
                    >
                      <ListItemButton 
                        sx={{height: 50}}
                        onClick={() => dispatch(switchTheme(theme.value))}
                        children={
                          <React.Fragment>
                            <ListItemIcon>
                              <Radio 
                                checked={theme.value === themeMode} 
                                size="small"
                                disableFocusRipple
                                disableTouchRipple
                              />
                            </ListItemIcon>
                            <ListItemText
                              primary={theme.label}
                              primaryTypographyProps={{
                                fontSize: 14,
                                m:0, p: 0
                              }}
                          />
                        </React.Fragment>
                      }
                    />
                      </ListItem>
                  ))
                }
              </List>
            </FormInputTheme>
            </Box>
          </Box>
        </Drawer>
    )
}