import { Select, MenuItem, FormControl, InputLabel } from '@mui/material';
import { useState, forwardRef, useLayoutEffect, useRef } from 'react';
import propTypes from 'prop-types';

const SelectOption = forwardRef ((props, ref) => {
    const {
        defaultValue, 
        onChange, 
        options, 
        label,
        disabled,
        size,
        color,
        margin,
        fullWidth,
        ...otherProps
    } = props;
    const [value, setValue] = useState(defaultValue);
    const selectProps = {...otherProps, value};
    const labelId = useRef('select-label-' + parseInt(Math.random * Math.pow(10, 6).toString()));
    const handleChange = (event, child) => {
        const { value } = child.props;
        if(typeof onChange === 'function')
            onChange(event, value);
        setValue(value);
    };
    useLayoutEffect(() => {
        if(ref) ref.current = value;
    },[value]);
    return (
        <FormControl 
            disabled={disabled} 
            size={size} 
            margin={margin} 
            fullWidth={fullWidth}
            color={color}
            id={labelId.current}
        >
            <InputLabel id={labelId.current}>{label}</InputLabel>
            <Select label={label} labelId={labelId.current} onChange={handleChange} {...selectProps}>
                {options.map((option, index) => (
                    <MenuItem
                        value={option.value}
                        key={index}
                    >{option.label}</MenuItem>
                ))}
            </Select>
        </FormControl>
    );
});

SelectOption.defaultProps = {
    options: [],
    defaultValue: '',
    onChange: null,
    label: '',
    disabled: false,
    size: 'normal',
    color: 'primary',
    fullWidth: false,
    margin: 'none',
};

SelectOption.propTypes = {
    options: propTypes.array,
    defaultProps: propTypes.string,
    label: propTypes.string,
    onChange: propTypes.oneOfType([
        propTypes.func,
        propTypes.object,
    ])
};

export default SelectOption;