import { createSlice } from "@reduxjs/toolkit";

const contacts = createSlice({
    name: 'contacts',
    initialState: {
        value: null,
    },
    reducers: {
        addContact (state, action) {
            state.value = action.payload;
        }
    }
});

export const { addContact } = contacts.actions;

export default  contacts.reducer;