import { Box } from "@mui/material";
import * as React from "react";
import { useSelector } from "react-redux";
import serverPath from "../../../services/serverPath";
import Chats from "./chats/Chats";
import NavRightHome from "./home/NavRightHome";

export default function NavRigth () {
    const chats = useSelector(state => state.chats.value);
    const token = useSelector(state => state.user.value.token);
    const contacts = useSelector(state => state.talkingContacts.value);
    const userId = (chats?.messages ? null : chats?._id);
    const [localMessages, setLocalMessages] = React.useState([])

/*
    POST api/chat/direct
        body = {
            to: Id du destinataire,
            date: date de l'envoi,
            file: fichier à envoyer
        }
*/
    React.useEffect(() => {
        localMessages.forEach(infos => {
            if(!infos.started) {
                const xhr = new XMLHttpRequest();
                xhr.open('post', URL);
                xhr.setRequestHeader('Authorization', `Bearer ${token}`);
                const formData = new FormData();
                formData.append('to', infos.userId);
                formData.append('type', infos.type);
                formData.append('date', infos.createdAt);
                formData.append('file', infos.file);
                
                xhr.onloadstart = () => {
                    console.log(xhr);
                    setLocalMessages(
                        localMessages.map(fileInfo =>
                            fileInfo._id === infos._id ? {
                                ...fileInfo,
                                xhr,
                                onProgress: xhr.upload,
                                started: true,
                             } : fileInfo
                            )
                    )
                };

                xhr.onload = (event) => { 

                    // setLocalMessages(
                    //     localMessages.map(fileInfo =>
                    //         fileInfo._id === infos._id ? {
                    //             ...fileInfo,
                    //             xhr,
                    //             onProgress: xhr.upload,
                    //             started: true,
                    //          } : fileInfo
                    //         )
                    // )

                    console.log(event);

                };

                xhr.onerror = (event) => { 
                    
                    // setLocalMessages(
                    //     localMessages.map(fileInfo =>
                    //         fileInfo._id === infos._id ? {
                    //             ...fileInfo,
                    //             xhr,
                    //             onProgress: xhr.upload,
                    //             started: true,
                    //          } : fileInfo
                    //         )
                    // )

                    console.log(event);

                };

                xhr.send(formData);
                
            } else {

            }
        })
    }, [localMessages, setLocalMessages]);
   
    return (
        <Box sx={{display: 'flex', flex: 1}}>
            {chats ? 
            (<Chats
                localMessages={localMessages} 
                setLocalMessages={setLocalMessages}
            />):
            (<NavRightHome/>) 
            }
        </Box>
    )
}

const URL = serverPath('api/chat/file');