import {
    useContext,
    createContext,
    useState,
    useLayoutEffect,
} from "react";
import { io } from 'socket.io-client';
import localStorageData from './localStorageData';
import config from '../config/app.json'
import { authenticate } from "../redux/user";
import { store } from "../redux";
import serverPath from './serverPath';
import { addNotification } from "../redux/apps/livingroom/notifications";
import { getDocTypes } from "../redux/apps/archives/archivesNavRight";


const configContext = createContext(null);
const sessionContext = createContext(null);
const cookieContext = createContext(null);


export const ConfigProvider = configContext.Provider;
export const SessionProvider = sessionContext.Provider;
export const CookieProvider = cookieContext.Provider;

export const useConfig = () => useContext(configContext);
export const useSession = () => useContext(sessionContext);
export const useCookie = () => useContext(cookieContext);

export const useCookieParam = () =>  {
    const [values, setValues] = useState((localStorageData.get('local') || {}).cookie || null);
    const getCookie = () => (
       values ? {
           ...(values),
           createAt: undefined,
           duration: undefined,
        } : null
    );
    const actions = {
        getCookie,
        setCookie(value) {
            setValues({
                ...(values|| {}),
                ...value,
            });
        },
        cleanCookie() {
          setValues(null);
        },
    };
    localStorageData.set('local', {
        cookie: values,
    })
    return [values, actions];
};

export const useSessionParam = () =>  {
    const [values, setValues] = useState(localStorageData.get('session'));
    const getSession = (key) => (
       key ? (values ? values[key] || null : null) : values
    );
    const actions = {
        getSession,
        setSession(key, value) {
            const data = key === 'object' ? key : {[key]: value};
            setValues({
                ...(values || {}),
                ...data,
            });
        },
        cleanSession(key) {
            setValues(key ? {...(values || {}), [key]: undefined } : null);
        },
    }
    localStorageData.set('session', values);
    let socket;
/////////////////////////////////////////////////////////////////////////////////
    const { user } = values || {};

    if(user?.token) {
        store.dispatch(authenticate({
            token: user.token,
            email: user.email,
            firstName: user.firstName,
            lastName: user.lastName,
            tel: user.phoneCel,
            id: user.id,
            docTypes: user.docTypes,
            imageUrl: user.userImage,
            level: {
                grade: user.level.grade,
                role: user.level.role,
                permission: user.level.permission,
            },
        }));
        store.dispatch(getDocTypes(user.docTypes));
        const URI = serverPath(`/?token=${user.token}`);
        socket = io(URI);
//////////////////////////////////////////////////////////////////////////////////////
        socket.on('invitations', ({invitations}) => {
            store.dispatch(addNotification({ nbr: invitations.length, invitations}));
        })
   }
/////////////////////////////////////////////////////////////////////////////////

    return [{socket, ...values}, actions];
};

export const useConfigParam = () => {
    //console.log('screen', useMediaQuery(useTheme().breakpoints.up('md')));
    const initValues = {
        ...localStorageData.get('local') || {},
    }
    const [values, setValues] = useState({
        lang: initValues.lang || config.lang,
        themeMode: initValues.themeMode || config.theme.mode,
        settingsNav: false,
        // ...['lg', 'md', 'xs'].map()
    });
    const handleChangeProps = (prop, value) => {
        setValues({
            ...values,
            ...typeof prop === 'object' ? prop :
            {[prop]: value}
        });
    };
    useLayoutEffect(() => {
        document.documentElement
        .lang = values.lang;
    }, [values.lang]);
    const actions = storageType => ({
        handleChangeProps,
        handleChangeTheme (themeMode) {
            localStorageData.set('local', { themeMode });
            handleChangeProps({ themeMode });
        },
        handleChangeLang (lang) {
            localStorageData.set('local', { lang });
            handleChangeProps({ lang })
        }
    });
    return [values, actions];
};
