import * as React from 'react';
import {
    Box, Chip, 
    Divider, 
    Zoom,
} from '@mui/material';
import { 
    MessageBody, 
    MessageLeft, 
    MessageRight 
} from './messages';
import { useSelector } from 'react-redux';
import { useSession } from '../../../../../services/globalConfig';
// import generateId from '../../../../../utils/generateId';
// import ring from '../../../../../utils/ring';
// import receveSong from '../../../assets/Sharp-Sms.mp3';

// const receveRing = ring({src: receveSong, autoplay: false});

const sortMessages = messages => {
    const messagesObject = {};
    messages?.forEach(message => {
        const date = (new Date(message.createdAt))
        .toLocaleDateString('en',{ year: 'numeric', month: 'numeric', day: 'numeric', }, )
        .toString();
        if(messagesObject[date])
            messagesObject[date].push(message);
        else 
            messagesObject[date] = [message];
    });

   return Object.keys(messagesObject)
   .sort((a, b) => (new Date(a)).getTime() - (new Date(b)).getTime())
   .map(groupeMss => ({
        date: (new Date(groupeMss))
        .toLocaleDateString('fr', { 
            weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' 
        }).toString(),
        messages: messagesObject[groupeMss].sort((a, b) =>
            (new Date(a.createdAt)).getTime() - (new Date(b.createdAt)).getTime()
        ),
    }));
}

export default function NavRightContent ({
    messages:mss, 
    sender,
    localMessages, 
    setLocalMessages,
}) {
 
    const [messages, setMessage] = React.useState([]);
    const userId = useSelector(state => state.user.value.id);
    const content = React.useRef(null);
    const [{socket},] = useSession();

    React.useEffect(() => {
        setMessage(mss);
    },[mss]);

    React.useEffect(() => {
        socket.on('direct-chat', ({messages}) => {
            if(messages[messages.length - 1]?.sender._id !== userId) {
                // if(receveRing.audio.paused)
                //     receveRing.audio.play();
            };
            socket?.emit('direct-chat');
            setMessage(messages);
            content.current.scrollTo({
                top: content.current.scrollHeight,
                behavior: 'smooth',
            });
        });
    },[socket, userId]);

    React.useEffect(() => {
        content.current.scrollTo({
            top: content.current.scrollHeight,
        })
    },[messages]);

    return (
        <Box
            sx={{
                display: 'flex',
                flex: 1,
                flexDirection: 'column',
                background: theme => theme.palette.background.default,
                overflow:'hidden',
            }}
        >
            <MessageBody 
                ref={content}
            >

            <Zoom in={!mss}>
                <Box sx={{alignItems: 'center', justifyContent: 'center', display: 'flex'}}>
                    <Chip
                        label={`
                            Commencer une nouvelle discussion avec ${sender.lname} ${sender.mname  || ''} ${sender.fname}
                        `}
                    />
                </Box>
            </Zoom>
            
            {sortMessages([
                ...Array.isArray(messages) ?
                messages : [],
                ...localMessages,
                ]).map(({messages, date}, index) => (
                <React.Fragment key={index}>
                        <Divider sx={{my:4}}>
                            <Chip 
                                label={date} 
                            />
                        </Divider>
                    {
                    messages?.map((message, index, messages) =>  message.sender &&
                    <Box
                        key={index}
                        component={message.sender?._id === userId ?
                            MessageRight :  MessageLeft
                        }
                        message={message.content}
                        timestamp={message.createdAt}
                        photoURL=""
                        oneself={
                            index > 0 ? messages[index - 1].sender?._id === message.sender?._id : false
                        }
                        isLasted={
                            !(message.sender?._id === messages[index + 1]?.sender?._id) 
                        }
                        type={message.type}
                        displayName={ sender?.type === 'room' &&
                            (() => {
                                const { lname, mname, fname } = message.sender
                                return `${lname} ${mname} ${fname}`
                            })()
                        }
                        avatarProps={{
                            children:(() => {
                                const { lname, fname } = message.sender
                                return `${lname.charAt(0) + fname.charAt(0)}`
                            })()
                        }}
                    />
                    )
                    }
                </React.Fragment>
            ))}
            </MessageBody>
        </Box>
    )
}