import * as React from 'react';
import { 
    AppBar, 
    Avatar, 
    IconButton, 
    ListItemAvatar, 
    Toolbar, 
    Typography,
    Box
} from "@mui/material";
import MoreVertRoundedIcon from '@mui/icons-material/MoreVertRounded';
import Groups2RoundedIcon from '@mui/icons-material/Groups2Rounded';

export default function NavRightHeader ({user}) {
    const isRoom = user?.type === 'room';
    const name = isRoom ? user.name : `${user.lname} ${user.mname || ''} ${user.fname}`;
    
    return (
        <React.Fragment>
            <Box sx={{width: '100%', display: 'flex'}}>
                <AppBar position="relative" color="default">
                    <Toolbar>
                        <ListItemAvatar>
                            <Avatar
                                children={
                                    isRoom ?
                                    (<Groups2RoundedIcon/>) :
                                    `${user.lname.charAt(0) + user.fname.charAt(0)}`
                                }
                            />
                        </ListItemAvatar>

                        <Typography sx={{flexGrow: 1}} >
                        {name}
                        </Typography>
                        <IconButton
                            size="small"
                        >
                            <MoreVertRoundedIcon fontSize="small"/>
                        </IconButton>
                    </Toolbar>
                </AppBar>
            </Box>
        </React.Fragment>
    )
} 