import { 
    Alert,
    AlertTitle,
    CircularProgress, 
    Box as MuiBox,
    Fade, 
    CardMedia, 
    Stack,
    Divider
} from '@mui/material';
import useAxios from 'axios-hooks';
import propTypes from 'prop-types';
import * as React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { openApp, setBookTypes, setData } from '../../../redux/apps/medialibrary/medialibraryNavRight';
import serverPath from '../../../services/serverPath';
import Box from "../../../components/Box";
import _workspace_logo from  '../../../assets/5a229b479641b7.26338722151221741.webp';
import Typography from "../../../components/Typography";
import 'animate.css/source/attention_seekers/swing.css';
import _logo_geid from '../../../assets/geid_logo_blue_without_title.webp';

export const useGetData = (route, key, loadData) => {
    const localData = useSelector(state => state.medialibraryNavRight.value.data);
    const [{data, error}, refrech, ] = useAxios(URL_MEDIALIBRARY + route, {manual: true});
    const dispacth = useDispatch();
    React.useEffect(() => {
        let timer = null;
        if(loadData) {
            timer = localData[key] ? null : window.setTimeout(() => {
                refrech();
            }, 5000);
    
            if(data) {
                if(JSON.stringify(localData[key]) !== JSON.stringify(data)) 
                    dispacth(setData({[key]: data}));
            } else {
                if(!timer) refrech();
            }
        }
        return () => { 
            if(timer)
                window.clearTimeout(timer);
        }
    }, [data, localData, refrech, dispacth, key, loadData]);

    return [refrech, error];
};

export default function MediaLibraryCover ({loadData}) {
    const medialibraryNavRight = useSelector(state => state.medialibraryNavRight.value);
    const dispacth = useDispatch();
    const [getBooks, getBooksError] = useGetData('/bibliotheque', 'books', loadData);
    const [getImages, getImagesError] = useGetData('/phototheque', 'images', loadData);
    const [getFilms, getFilmsError] = useGetData('/filmotheque', 'films', loadData);
    const [{data:getBookTypes, error:getBookTypesError},] = useAxios(URL_MEDIALIBRARY_BOOKS, {manual: !loadData});
    const [error, setError] = React.useState(null);
   
    const {tab, data:{books, images, films}} = medialibraryNavRight;
    
    const open = !(books && images && films && getBookTypes);

    React.useEffect(() => {
        const refrech =  {
            getBooks,
            getImages,
            getFilms,
        };
        if(loadData && (tab !== 'home')) {
            if(typeof refrech[tab] === 'function') 
                refrech[tab]();
        }
        if(!open) 
            dispacth(openApp());
    }, [tab, open, loadData, dispacth, getBooks, getImages, getFilms]);

    /*Handle the all errors */
    React.useEffect(() => {
        const oneError = [
            getBooksError, 
            getImagesError, 
            getFilmsError, 
            getBookTypesError
        ].find(error => !!error);

        if(oneError && !error) 
            if((oneError.code === 'ERR_NETWORK') && !oneError.response?.data)
                setError({
                    title: 'Promblème de réseau',
                    message: `Impossible d'acceder à la mediathèque, 
                    votre apareil n'est pas connecté sur internet`
                });

    }, [
        getBooksError, 
        getImagesError, 
        getFilmsError, 
        error, 
        getBookTypesError
    ]);
    
    React.useEffect(() => {
        if(getBookTypes) 
                dispacth(setBookTypes({bookTypes: getBookTypes}));
    }, [getBookTypes]);

    return ( open &&
        <Box
            sx={{
                justifyContent: 'center',
                alignItems: 'center',
                userSelect: 'none',
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                bgcolor:'background.paper',
                zIndex: theme => theme.zIndex.drawer,
            }}
        >
           <Stack
            display="flex"
            justifyContent="center"
            alignItems="center"
            flex={1}
            spacing={1}
           >
            <CardMedia
                    component="img"
                    src={_workspace_logo}
                    draggable={false}
                    sx={{
                        height: 100,
                        width: 100,
                        animation: 'swing .5s 1s' ,
                    }}
            />
            <MuiBox
                display="flex"
                justifyContent="center"
                alignItems="center"
                flexDirection="column"
                position="relative"
            >
                <Stack 
                    spacing={1} 
                    direction="row" 
                    width={500} 
                    my={1}
                    divider={
                        <Divider 
                            flexItem 
                            orientation="vertical" 
                            sx={{
                                bgcolor: 'text.primary',
                                borderWidth: 1,
                            }}
                        />
                    }
                    display="flex"
                    justifyContent="center"
                >
                    <CardMedia
                        component="img"
                        src={_logo_geid}
                        sx={{width: 120}}
                    />
                    <Typography
                        noWrap
                        variant="h4"
                    >Mediathèque</Typography>
                </Stack>
                <Fade in={loadData}>
                        {!!error ?
                       ( <Alert
                            severity='error'
                            children={
                                <React.Fragment>
                                    <AlertTitle>{error.title}</AlertTitle>
                                    {error.message}
                                </React.Fragment>
                            }
                        />) :
                        (<CircularProgress
                            size={15}
                            color="inherit"
                            sx={{position: 'absolute', top: '150%'}}
                        />)}
                    </Fade>
            </MuiBox>
           </Stack>
           <Typography  variant="caption" paragraph>
                Direction Archives et Nouvelles Technologie de l'Information et de la Communication ©2022
            </Typography>
        </Box>
    );
}

MediaLibraryCover.defaultProps = {
    loadData: false,
};
   

MediaLibraryCover.propTypes = {
    loadData: propTypes.bool,
};

const URL_MEDIALIBRARY = serverPath('/api/stuff');
const URL_MEDIALIBRARY_BOOKS = serverPath('/api/stuff/bibliotheque/types');