import * as React from 'react';
import {
    Button,
    CardActionArea,
    Fade,
} from '@mui/material';
import MenuOptions from '../../../components/MenuOptions';
import VerifiedRoundedIcon from '@mui/icons-material/VerifiedRounded';
import DeleteRoundedIcon from '@mui/icons-material/DeleteRounded';
import InfoRoundedIcon from '@mui/icons-material/InfoRounded';
import { useSelector } from 'react-redux';
import useAxios from 'axios-hooks';
import serverPath from '../../../services/serverPath';
import { useSnackbar } from 'notistack';

export default function FileWrapper ({children, file, uris}) {
    const [contextMenu, setContextMenu] = React.useState(null);
    const { enqueueSnackbar, closeSnackbar } = useSnackbar();
    const [show, setShow] = React.useState(true);
    const [{loading}, refech, cancel] = useAxios(null, {manual:true});
    const {token, id:userId} = useSelector(state => state.user.value);
    const { validate, del, frozenType } = uris;

    const handleContextMenu = event => {
      event.preventDefault();
      
      setContextMenu(
        contextMenu === null
          ? {
              mouseX: event.clientX + 2,
              mouseY: event.clientY - 6,
            }
          :null,
      );
    };

    const handleValidate = event => {
        const timer = setTimeout(() => {
            const frozenId = file._id;
            refech({
                url: serverPath(validate),
                method: 'post',
                data: { userId, frozenId},
                headers: {
                    Authorization: `Bearer ${token}`,
                }
            }).then(() => {
                closeSnackbar();
                enqueueSnackbar(
                    'Validation fichier effectuée avec succèss', 
                    {variant: 'success', onClose: closeSnackbar }
                );
                setShow(false);
            }).catch(
                () => {
                    closeSnackbar()
                    enqueueSnackbar(
                        'Impossible de valider le fichier, Un promblème est survenu',
                        {variant: 'error', onClose: closeSnackbar}
                    );
                })

        }, 2000);
        enqueueSnackbar(
            'Validation en cours...', {
                title: file.title,
                action: (
                    <Button 
                        color="inherit" 
                        size="small"
                        children="annuler"
                        onClick={() => {
                            if(loading)
                                cancel();
                            window.clearTimeout(timer);
                            closeSnackbar();
                        }}
                    />
                )
        });
    };

    const handleDelete = event => {
        const timer = setTimeout(() => {
            const data = JSON.stringify({
                frozenType,
                frozenId: file._id,
                userId,
            });

            refech({
                url: serverPath(del + data),
                method: 'delete',
                headers: {
                    Authorization: `Bearer ${token}`,
                }
                
            }).then(() => {
                closeSnackbar();
                setShow(false);
            }).catch(
                () => {
                    closeSnackbar()
                    enqueueSnackbar(
                        'Impossible de supprimer le fichier, Un promblème est survenu', 
                        {variant: 'error', onClose: closeSnackbar}
                    );
                })

        }, 2000);

        enqueueSnackbar(
            'Suppression en cours...', {
                title: file.title,
                action: (
                    <Button 
                        color="inherit" 
                        size="small"
                        children="annuler"
                        onClick={() => {
                            setShow(true);
                            if(loading)
                                cancel();
                            window.clearTimeout(timer);
                            closeSnackbar();
                        }}
                    />
                )
        });
        setShow(false);
    };

    const handleClose = () => {
      setContextMenu(null);
    };

    const options = [
        {
            label: 'Valider',
            icon: VerifiedRoundedIcon,
            action: handleValidate,
        },
        {
            label: 'Supprimer',
            icon: DeleteRoundedIcon,
            action: handleDelete,
        },
        {
            label: 'Details',
            icon: InfoRoundedIcon,
            action () {

            }
        },
        
    ]
    return(
        <React.Fragment>
            <Fade in={show} style={{
                display: 'flex', 
                width: '100%', 
                justifyContent: 'center', 
                alignItems: 'center',
            }}>
                <CardActionArea
                    onContextMenu={handleContextMenu}
                >
                {children}
                </CardActionArea>
            </Fade>
            <MenuOptions
                open={contextMenu !== null}
                onClose={handleClose}
                anchorReference="anchorPosition"
                anchorPosition={
                  contextMenu !== null
                    ? { top: contextMenu.mouseY, left: contextMenu.mouseX }
                    : undefined
                }
                options={options}
            />
        </React.Fragment>
    )
}