import * as React from 'react';
import { 
    ClickAwayListener,
    IconButton,
    Box,
} from "@mui/material";
import AttachFileRoundedIcon from '@mui/icons-material/AttachFileRounded';
import SpeedDial from '@mui/material/SpeedDial';
import SpeedDialIcon from '@mui/material/SpeedDialIcon';
import SpeedDialAction from '@mui/material/SpeedDialAction';

import photoIconImage from '../../../../../icons/icons8-image-64.png';
import documentIconImage from '../../../../../icons/icons8-structure-des-prix-48.png';
import audioIconImage from '../../../../../icons/icons8-musique-64.png';
import videoIconImage from '../../../../../icons/icons8-video-64.png';

import asyncGetFile from '../../../../../services/asyncGetFile';
import ImgToIcon from '../../../../../icons/ImgToIcon';

const actions = [
  { icon: videoIconImage, name: 'Vidéo', type: 'video' },
  { icon: photoIconImage, name: 'Photo', type: 'image' },
  { icon: audioIconImage, name: 'Audio', type: 'audio' },
  { icon: documentIconImage, name: 'Document', type: 'document' },
];

export default function SpeedDialOptions ({handleFile}) {
    const [open, setOpen] = React.useState(false);
    return (
        <React.Fragment>
           <ClickAwayListener
             onClickAway={() => setOpen(false)}
           > 
           <Box
            sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                mr:1,
            }}
           >
                <SpeedDial
                    ariaLabel="Jointure d'un document ou media"
                    sx={{ position: 'absolute', bottom: 40 }}
                    hidden
                    open={open}
                    icon={<SpeedDialIcon />}
                    >
                    {actions.map((action) => (
                        <SpeedDialAction
                            key={action.name}
                            icon={
                                <ImgToIcon
                                    size={25}
                                    src={action.icon}
                                />
                                }
                            tooltipTitle={action.name}
                            arrow
                            sx={{p: 2}}
                            onClick={async () => {
                                const [ file ] = await asyncGetFile({accept: `${action.type}/*`});
                                if(file) {
                                    setOpen(false);
                                    handleFile(file);
                                }
                            }}
                        />
                    ))}
                </SpeedDial>
                <IconButton 
                    color="inherit"
                    onClick={() => setOpen(!open)}
                    sx={{
                        position: 'relative',
                        zIndex: theme => theme.zIndex.drawer,
                        ...open ? {
                            bgcolor: theme => theme.palette.divider,
                            transition: 'none',
                            '&:hover': {
                                bgcolor: theme => theme.palette.divider,
                                '--rgb-background':' 262, 240, 283',
                            }
                        } : {}
                    }}
                >
                    <AttachFileRoundedIcon />
                        
                </IconButton>
           </Box>
           </ClickAwayListener>
        </React.Fragment>
    );
}