import { 
    IconButton, 
    useTheme,
    Zoom,
} from "@mui/material";
import SendRoundedIcon from "@mui/icons-material/SendRounded";
import KeyboardVoiceRoundedIcon from "@mui/icons-material/KeyboardVoiceRounded";

export default function VoiceToSendIcon ({variant, onSendText}) {
    const isVoice = variant === 'voice';
    const theme = useTheme();
    const transitionDuration = {
        enter: theme.transitions.duration.enteringScreen,
        exit: theme.transitions.duration.leavingScreen,
    };
    return (
        <IconButton 
            color="inherit" 
            sx={{position: 'relative', ml: 1}} 
            disabled={isVoice}
            onClick={onSendText}
        >
            <SendRoundedIcon sx={{color: 'transparent'}}/>
            <Zoom 
                timeout={transitionDuration}
                in={!isVoice}
                style={{
                    transitionDelay: `${ isVoice ? 1 : 0}ms`,
                    position: 'absolute',
                }}
                unmountOnExit
            >
                <SendRoundedIcon/>
            </Zoom> 
            <Zoom 
                timeout={transitionDuration}
                in={isVoice}
                style={{
                    transitionDelay: `${ isVoice ? 1 : 0}ms`,
                    position: 'absolute',
                }}
                unmountOnExit
            >
                <KeyboardVoiceRoundedIcon/>
            </Zoom>
        </IconButton>
    )
}