import { createSlice } from "@reduxjs/toolkit";
import * as _ from 'lodash';
import persistReducer from "redux-persist/es/persistReducer";
import session from "redux-persist/lib/storage/session";

const initialState = {
    value: {
        token: null,
        email: null,
        firstName: null,
        lastName: null,
        tel: null,
        permission: [],
        isAuthenticated: false,
        level: {
            grade: null,
            role: null,
        },
    },
};

const user = createSlice({
    name: 'user',
    initialState,
    reducers: {
        authenticate (state, action) {
            state.value = {
                ...action.payload,
                isAuthenticated: action.payload.token ? true : false,
            }
        },
        addUserKey (state, actions) {
            state.value = {
                ...state.value,
                ...actions.payload,
            }
        },
        disconnecte (state) {
            state.value = {
                ...initialState,
                email: state.value.email,
                firstName: state.value.firstName,
                lastName: state.value.lastName,
                tel: state.value.tel,
            }
        },
        remove (state, action) {
            const key = action.payload;
            state.value = {
                ...key === undefined ? initialState : 
                _.isArray(key) ? ((() => {
                    const removeState = {};
                    key.forEach(removeKey => {
                        removeState[removeKey] = initialState[removeKey];
                    })
                })()) :
                { [key] : initialState[key], }
            };
        },
    }
});

export const { authenticate, disconnecte, forgot, addUserKey} = user.actions;
export default persistReducer({
    storage: session,
    key: 'geid_user'
}, user.reducer);