import {
    Box
} from '@mui/material';
import { useSelector } from 'react-redux';
import ArchivesContent from './ArchivesContent';
import MedialibraryContent from './MedialibraryContent';

export default function CensorshipNavRightContent () {
    const app = useSelector(state => state.censorshipNavRight.value.app);
    
    return (
        <Box
            sx={{
                display: 'flex',
                flex: 1,  
                overflow: 'auto',
            }}
        >
          {app === 'archives' && <ArchivesContent/>}
          {app === 'medialibrary' && <MedialibraryContent/>}
        </Box>
    );
}