export default function refStructObj (obj={}, keyRef={}, one=false) {
    const oldObj = {...obj};
    const newObj = {};
    Object.keys(oldObj).forEach(el => {
        if(el) {
            const newRefKey = keyRef[el];
            if(newRefKey) {
                newObj[newRefKey] = oldObj[el];
                delete oldObj[el];
            }
        }
    });
    return one ? newObj : {...oldObj, ...newObj};
}