import * as React from 'react';
import {
    Box,
    Slide,
    Stack,
} from '@mui/material';
import WorkspacesHeader from './views/WorkSpaceHeader';
import WorkspacesNavLeft from './views/WorkspaceNavLeft';
import WorkspacesContent from './views/WorkspacesContent';
import deviceDetector from '../../services/deviceDetector';
import UnderMaintenance from '../../components/UnderMaintenance';import { onApp } from '../app';
;

export const WorkspacesProps = React.createContext(null);

export default function Workspaces() {
    const [values, setValues] = React.useState({
        openNavLeft: false,
        fullScreen: false,
        data: {
            documents: [],
            images: [],
            videos: [],
            others: [],
        },
    });
    const currentTab = React.useRef('documents');
    const mainContainer = React.useRef();
    const handleChangeProps = (prop, value) => event => setValues({
        ...values,
       ...( typeof prop === 'object' ? prop : {[prop]: value})
    });

    React.useEffect(() => {
        const fullScreenChange = (event) => {
            setValues({
            ...values,
            fullScreen: !!document.fullscreenElement

        })};
        document.body.addEventListener('fullscreenchange', fullScreenChange);
    },[values.fullScreen]);
    React.useEffect(() => { onApp('workspaces') }, [])
    
  return (
     deviceDetector() ?
        <UnderMaintenance/> :
    <Slide
        in={true}
        direction="up"
    >
        <Box ref={mainContainer}>
            <WorkspacesProps.Provider 
                value={[{...values, mainContainer, currentTab,}, handleChangeProps]}
            >
                <Stack
                    direction="row"
                    display="flex"
                    flex={1}
                    height='100vh'
                >
                    <Box
                        sx={{
                            bgcolor: 'background.paper',
                            display: 'flex',
                            position: 'relative',
                            flex: values.openNavLeft ? .3 : 0,
                            overflow: 'hidden',
                            justifyContent: 'center',
                            alignContent: 'center',
                            transition: theme => theme.transitions.create('flex', {
                                easing: theme.transitions.easing.sharp,
                                duration: theme.transitions.duration.leavingScreen,
                            }),
                        }}
                    >
                        <WorkspacesNavLeft/>
                    </Box>
                    <Box
                        sx={{ display: 'flex', flex: 1, }}
                    >
                        <Box
                            sx={{
                                height: '100%',
                                display: 'block',
                                width: '100%',
                            }}
                        >
                            <Box sx={{ flexGrow: 1}}>
                                <WorkspacesHeader
                                    headerPropsButton={{
                                        uploadNavClick() {
                                            const uploadNav = !values.uploadNav;
                                            handleChangeProps({uploadNav})(null);
                                        },
                                    }}
                                />
                                <WorkspacesContent
                                    tab={currentTab.current}
                                    data={values.data}
                                    openNavLeft={values.openNavLeft}
                                />
                            </Box>
                        </Box>
                    </Box>
                </Stack>
            </WorkspacesProps.Provider>
        </Box>
    </Slide>
  );
}