import { createSlice } from "@reduxjs/toolkit";

const invitationNav = createSlice({
    name: 'invitationNav',
    initialState: {
        value: {
            open: false,
            date: null,
            type: 'direct' || 'room',
            mode: 'email' || 'contact'
        }
    },
    reducers: {
        close (state) {
            state.value = {
                ...state.value,
                open: false,
                date: null,
                type: 'direct' || 'room',
            };
        },
        open (state, action) {
            state.value = {
                ...state.value,
                open: true,
                ...action.payload,
            };
        },
    }
});

export const { close, open, } = invitationNav.actions;
export default  invitationNav.reducer;