import { createSlice } from "@reduxjs/toolkit";

const fastContactNav = createSlice({
    name: 'fastContactNav',
    initialState: {
        value: {
            open: false,
            mode: null,
        }
    },
    reducers: {
        close (state) {
            state.value = {
                ...state.value,
                open: false,
                mode: 'select',
            };
        },
        openSelect (state) {
            state.value = {
                ...state.value,
                open: true,
                mode: 'select',
            };
        },
        open (state) {
            state.value = {
                ...state.value,
                open: true,
                mode: 'only',
            };
        },

    }
});

export const { close, open, openSelect } = fastContactNav.actions;
export default  fastContactNav.reducer;