const MediaReader = ({src, type}) => {
  return (
  <Box
    sx={{
      display: 'inline-block',
      //: 'linear-gradient(transparent, black)',
      position: 'relative',
      bgcolor: 'red',

    }}
    LinkComponent="a"
    target="_blank"
    href={src}
    component={CardActionArea}
  >
    <CardMedia
      src={src}
      component={type}
      sx={{mb: - 1, maxHeight: 200}}
    />
  </Box>)
};

const FileFrame = ({file}) => {

  const info = fileExtensionBase.find(file => 
    ~file.exts.indexOf(
        getFileExtension(file?.name)
        )
    );


  if(~['image', 'video', 'document'].indexOf(file.type))
    return (
    <MediaReader
      src={file.src}
      type={({
        video: 'video',
        image: 'img',
        document: 'iframe',
      })[file.type]}
    />
    )

};

export const MessageLeft = ({
  message, 
  timestamp, 
  photoURL, 
  displayName, 
  avatarProps,
  type,
  oneself,
  isLasted,
}) => {

  const date = new Date(timestamp);
  const classes = useStyles();
  const ext = getFileExtension(message);
  const file = {
    ...(fileExtensionBase.find(format => ~format.exts.indexOf(ext)) || {}),
    src: message,
    ext,
  };
  
  return (
    <Zoom in>
        <Box
          sx={{
            position: 'relative',
            mb: isLasted ? 3 : 0
          }}
        >
          { !oneself &&
            <React.Fragment>
              <Avatar
                {...avatarProps}
                src={photoURL}
                sx={{
                  position: 'absolute',
                  width: 32,
                  height: 32,
                  fontSize: 12
                }}
              />
              <Typography sx={{ml:5}} variant="caption" color="text.secondary">{displayName}</Typography>
            </React.Fragment>
          }
          <Box className={classes.messageRow}>
            <Box className={[classes.messageRight, !oneself && classes.arrowRight]} sx={{boxShadow: 5}}>
              {type === 'text' && <p className={classes.messageContent}>{message}</p>}
              {type === 'file' && 
                <FileFrame
                  file={file}
                >{message}</FileFrame>}
                <Box sx={{mt:1, mx:1, mb:.5}}>
                  <Typography 
                      className={classes.messageTimeStampRight}
                  >
                  {date.getHours()}:{date.getMinutes().toString().padStart(2, '0')}
                  </Typography>
                </Box>
            </Box>
          </Box>

        </Box>
      </Zoom>
  );
};

export const MessageRight = ({message, timestamp, type, oneself, isLasted,}) => {
  const classes = useStyles();
  const ext = getFileExtension(message);
  const file = {
    ...(fileExtensionBase.find(format => ~format.exts.indexOf(ext)) || {}),
    src: message,
    ext
  };
  const date = new Date(timestamp);

  return (
    <Zoom in>
        <Box 
            className={classes.messageRowRight}
            sx={{
              mb: isLasted ? 3 : 0
            }}
        >
          <Box className={[classes.messageLeft, !oneself && classes.arrowLeft]} sx={{boxShadow: 5}}>
            {type === 'text' && <p className={classes.messageContent}>{message}</p>}
            {type === 'file' && 
            <FileFrame
              file={file}
            >{message}</FileFrame>}
            <Box sx={{mt:1, mx:1, mb:.5}}>
                  <Typography className={classes.messageTimeStampRight}>
                  {date.getHours()}:{date.getMinutes().toString().padStart(2, '0')}
                  </Typography>
            </Box>
          </Box>
        </Box>
    </Zoom>
  );
};

