import * as React from "react";
import { 
    Button,
    DialogActions,
    DialogContent, 
    List, 
    Box,
} from "@mui/material";
import { close } from "../../../redux/apps/livingroom/fastContactNav";
import ContactItem from "../component/ContactItem";
import LoadingList from "../component/LoadingList";
import { useDispatch } from "react-redux";
import { startChat } from "../../../redux/apps/livingroom/chats";

export default function FastContacts (props) {
    const {users, mode, usersRef, onNext} = props;
    const dispatch = useDispatch();
    const [usersSelected, setUsersSelected] = React.useState(usersRef.current);

    const handleClickList = (contact, mode) => () => {
        if(mode === 'select') {
            if(usersSelected.find(user => user._id === contact._id))
                setUsersSelected([
                    ...usersSelected.filter(user => user._id !== contact._id) 
                ]);
            else 
                setUsersSelected([
                    ...usersSelected,
                    contact,
                ]);
        } else {
            dispatch(startChat(contact));
            dispatch(close());
        }
    };

    React.useEffect(() => {
        usersRef.current = usersSelected;
    },[users, usersSelected, usersRef]);

    return (
        <Box 
            sx={{
                flex:1,
                display: 'flex',
                flexDirection: 'column',
                width: 400,
                minHeight: 300,
            }}
        >
            {users?.length === 0 ?
            (<LoadingList/>) :
            (<React.Fragment>
                <DialogContent>
                    <List disablePadding>
                    {users.map((contact, index) => ( 
                        <React.Fragment key={index}>
                            <ContactItem
                                key={contact._id}
                                disabledSecondaryAction
                                mode={mode}
                                onClick={handleClickList(contact, mode)}
                                name={`${contact.lname} ${contact.mname} ${contact.fname}`}
                                message={contact.email}
                                checkboxProps={{
                                    checked: !!usersSelected.find(user => user._id === contact._id),
                                    onClick: handleClickList(contact, mode),
                                }}
                                divider={(users.length - 1) !== index}
                            />
                        </React.Fragment>
                    ))}
                    </List>
                </DialogContent>
                <DialogActions>
                    {mode === 'select' && 
                    <Button 
                        variant="contained" 
                        size="small"
                        disabled={!usersSelected.length}
                        onClick={onNext}
                    >suivant</Button>}
                    <Button 
                        size="small"
                        onClick={() => dispatch(close())}
                    >annuler</Button>
                </DialogActions>
            </React.Fragment>)}
        </Box>
    )
}