import { 
    Stack, 
    Typography,
    Box, 
} from "@mui/material";
import React from "react";
import { useSelector } from "react-redux";
import InvitationList from "./InvitationList";

export default function Notifications () {
    const { nbr } = useSelector(state => state.notifications.value);
    
    return ( 
        <Box
            sx={{
                width: '100%', 
                display: 'flex', 
                flex: 1, 
                flexDirection: 'column', 
                height: '100%',
            }}
        >
        {nbr ?
        (<React.Fragment>
            <InvitationList/>
        </React.Fragment>) :
        (<Stack
            display="flex"
            flex={1}
            width="100%"
            height="100%"
            justifyContent="center"
            alignItems="center"
        >
            <Typography 
                component="div" 
                color="text.secondary" 
                variant="body2"
                aling="center"
            >
                Aucune notification
            </Typography>
        </Stack>)}
        </Box>
    )
}