import StackPaper from "../../../../components/StackPaper";
import {
    Grid,
    Box,
} from '@mui/material';
import FileWrapper from "../../components/FileWrapper";
import { useSelector } from "react-redux";

export default function DocsContent ({data, uris}) {
    const isSmall = useSelector(state => state.censorshipNavLeft.value.open);

    return (
        <Box
            sx={{display: 'flex', flex: 1, m: 1}}
        >
           <Grid container spacing={0} >
            {data?.map((doc, index) => (
                <Grid item key={index} xs={isSmall ? 2 : 12/9}>
                    <Box
                        sx={{
                            display: 'flex', 
                            width: '100%', 
                            justifyContent: 'center', 
                            alignItems: 'center',
                        }}
                    >
                        <FileWrapper 
                            file={doc}
                            uris={uris}
                        >
                            <StackPaper
                                src={doc.fileUrl}
                                coverSrc={doc.coverUrl}
                                name={doc.description}
                            /> 
                       </FileWrapper>    
                    </Box>
                </Grid>
            ))}
           </Grid>
        </Box>
    );
}