import { createSlice } from "@reduxjs/toolkit";

const talkingContacts = createSlice({
    name: 'talkingContacts',
    initialState: {
        value: null,
    },
    reducers: {
        addContact (state, action) {
            state.value = action.payload;
        }
    }
});

export const { addContact } = talkingContacts.actions;

export default  talkingContacts.reducer;