import { useRef } from 'react';
import serverPath from '../../../services/serverPath';
import { useSession } from '../../../services/globalConfig';
import localStorageData from '../../../services/localStorageData';
import fileExtensionBase from '../../../config/fileExtensionBase';
import getFileExtension from '../../../services/getFileExtension';
import useAxios from 'axios-hooks';

export default function useDelete (file) {
    const [{loading}, refetch, cancel] = useAxios(URL, { manual: true});
    const [,{ getSession }] = useSession();
    const {id: userId, token, } = getSession('user') || {};
    const cancelTime = useRef(null);
    const path = fileExtensionBase
            .find(extItem => ~extItem.exts.indexOf(getFileExtension(file.name))
    )?.type || {};
    const params = localStorageData.parse ({
        userId,
        path: /document|image|video/.test(path) ? path + 's' : 'documents',
        filename: file.name,
    });
    const handleDelete = (startCallback, endCallback) => () => {
          cancelTime.current = window.setTimeout(() => {
          refetch({
              url: URL + params,
              method: 'delete',
              headers: {
                  'Authorization': `Bearer ${token}`
              }
          }).then(result => {
              if(typeof endCallback === 'function')
                  endCallback(null, result.data);

          }).catch(error => {
              if(typeof endCallback === 'function')
                  endCallback(error);
          });
        }, 3000);
        if(typeof startCallback === 'function')
            startCallback();
    }
    const cancelDelete = () => {
      if(cancelTime.current)
        window.clearTimeout(cancelTime.current);
      cancel();
    }
    return [handleDelete, loading, cancelDelete];
}

const URL = serverPath('/api/stuff/workspace/');
