import { useMediaQuery, useTheme } from "@mui/material";

const screenKey = ['xl', 'lg', 'md', 'xs'];
const defaultParam = {};
screenKey.forEach(screen => defaultParam[screen] = screen);
export default function useSize (params = {}) {
    const theme = useTheme();
    const isThisScreens = [
        useMediaQuery(theme.breakpoints.up('xl')),
        useMediaQuery(theme.breakpoints.up('lg')),
        useMediaQuery(theme.breakpoints.up('md')),
        useMediaQuery(theme.breakpoints.up('xs')),
    ];
    const i = isThisScreens.findIndex(isTrue => isTrue);
    return {
        key: defaultParam[screenKey[i]],
        value (params = params) {
            return {...defaultParam, ...params}[screenKey[i]]
        }
    };
}
