import {
  Dialog,
  DialogContent,
  DialogTitle,
  DialogActions,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  useTheme,
  Button,
} from '@mui/material';
import CalendarMonthRoundedIcon from '@mui/icons-material/CalendarMonthRounded';
import fileExtensionBase from '../config/fileExtensionBase';
import getFileExtension from '../services/getFileExtension';
//import CropText from './CropText';
import ImgToIcon from '../icons/ImgToIcon';
import normaliseOctetSize from '../services/normaliseOctetSize';

export default function About (props) {
  const { file, ...otherProps } = props;
  const { size, lastModifiedDate, name, type } = file;
  const date = new Date(lastModifiedDate);
  const extension = getFileExtension(name);
  const theme = useTheme();
  const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';

  return (
    <Dialog 
      {...otherProps}
      BackdropProps={{
        sx: {
          backdropFilter: 'blur(15px)',
        }
      }}
    >
      <DialogTitle>Détails</DialogTitle>
        <DialogContent>
          <List
            sx={{width: 500}}
          >
            <ListItem>
              <ListItemIcon>
                <CalendarMonthRoundedIcon/>
              </ListItemIcon>
              <ListItemText
                primary={date.toLocaleDateString('fr-FR', optionParams)}
                secondary={`${
                  date.getHours()}:${
                  date.getMinutes()}:${
                  date.getSeconds()}`
                }
              />
            </ListItem>
            <ListItem>
              <ListItemIcon>
                <ImgToIcon
                  size={25}
                  src={
                    (fileExtensionBase.find(item => ~item.exts.indexOf(extension)) || {} ).icon
                  }
                />
              </ListItemIcon>
              <ListItemText
                primary={
                    (() => {
                      let newName = '';
                      const limite = 50;
                      for (let i = 0; i < name.length; i += limite)
                        newName += ' ' + name.slice(i, i + limite);
                      return newName;
                    })()
                }
                secondary={`${normaliseOctetSize(size)} ${type || ''}`}
                primaryTypographyProps={{
                }}
              />
            </ListItem>
          </List>
        </DialogContent>
        <DialogActions>
          <Button
            onClick={otherProps.onClose}
            size="small"
            variant="outlined"
            color={color}
            children="ok"
          />
        </DialogActions>
    </Dialog>
  )
}

const optionParams = {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
};
