import { createSlice } from "@reduxjs/toolkit";

const censorshipData = createSlice({
    name: 'censorshipData',
    initialState: {
        value: {}
    },
    reducers: {
        addData (state, actions) {

            state.value = {
                ...state.value,
                [actions.payload.value.key]: actions.payload.value.data,
            }
        },
    }
});

export const { addData } = censorshipData.actions;
export default censorshipData.reducer;